#!/usr/bin/env node
// Single source of truth for the ORRERY evolution & fidelity backlog.
// Emits  briefs/evolution-backlog.md  and  site/evolution.html  so the two cannot drift.
//
//   node scripts/evolution.mjs
//
// x:  SIM = simulation truth · EYE = what the player sees · BOTH.
// e:  effort S/M/L.  i: impact 1..3.
// k:  capability token this item provides.  n: tokens it needs first.

import { writeFile, mkdir } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');

const CATS = [
  ['time', 'Deep time and the ages of life',
    'The prototype advances 200 years a tick and names an era every 48,000 of them. Earth’s biosphere is 3.7 billion years old and 88% of that is microbes. Until the clock is honest about proportion, nothing downstream can read as history.'],
  ['metab', 'Metabolism before morphology',
    'Life is currently a 0–1 scalar with an eight-rung ladder bolted on, and the rungs are body plans. For the first three billion years the interesting variable was not shape, it was which electron went where. Rebuild the biosphere on a redox tower and the Archean stops being a loading screen.'],
  ['trans', 'The major evolutionary transitions',
    'Maynard Smith and Szathmáry’s framing, updated: a handful of one-off changes in how information is stored and inherited, each of which made everything after it possible. These should be contingent, gated, and occasionally never happen at all.'],
  ['genome', 'Genomes, traits and open-ended evolution',
    '`lifeClass` is a Uint8 index into a fixed array of eight. That is a taxonomy, not an evolutionary process. Give populations a heritable trait vector and the ladder becomes a tree that you did not author.'],
  ['eco', 'Ecology: who eats whom',
    'Three global scalars — herbivore, carnivore, meanLife — stand in for the entire trophic structure of a planet. Almost every legible ecological pattern is a consequence of energy transfer efficiency and body-size scaling, both of which are arithmetic.'],
  ['biogeo', 'Biogeography: life on a sphere',
    'You already have plates, coastlines and climate bands. Biogeography is the free consequence of running life on top of them, and it is where a planet stops being uniform and starts having *places*.'],
  ['extinct', 'Extinction, recovery and contingency',
    'The prototype has one dieback event and a plague scalar. Mass extinctions are the load-bearing structure of the fossil record: each has a specific kill mechanism, a specific recovery time, and a specific set of survivors that inherit the world.'],
  ['chem', 'Biogeochemistry: life as a planetary process',
    'This is the actual thesis of SimEarth and the reason the game mattered. Life does not sit on the planet; it *is* one of the planet’s chemical cycles, and the atmosphere you breathe is a waste product buried in rock.'],
  ['gaia', 'Gaia, updated and argued with',
    'Daisyworld is currently a playable world. It was never a world — it was a proof that regulation needs no foresight. Modern Earth-system science has moved to tipping elements, rate sensitivity and an honest fight about whether Gaia is real at all.'],
  ['alien', 'Biospheres that are not Earth’s',
    'The catalogue holds 120 real bodies and every one of them currently runs Earth’s biology with a colour filter. The interesting question a god-game can ask is what life looks like when the solvent, the energy source or the star is wrong.'],
  ['surface', 'Visual fidelity: the surface',
    'Colour is presently a per-ruleset function of five scalars. Everything that makes a real planet photograph beautifully — glint, phenology, sediment, snow line, ice texture — is a consequence of fields you are already simulating and throwing away at draw time.'],
  ['air', 'Visual fidelity: air, light and sky',
    'One analytic rim term and a cloud shell. Atmospheric scattering is the single highest-yield rendering investment available here, because it is what makes a sphere read as a *world* rather than a textured ball.'],
  ['body', 'Visual fidelity: bodies and morphology',
    'Entities are 16 hand-drawn SVG sprites on camera-facing quads. If evolution is going to be the subject, the things evolving have to be generated by the same trait vector that evolves.'],
  ['instr', 'Instruments: seeing evolution happen',
    'Bound by the product brief’s "every number is a place" rule. These are diegetic scientific instruments — a core sampler, a phylogeny you can hold, a spectrograph pointed at your own planet — not overlays.'],
  ['craft', 'Craft, calibration and honesty',
    'What it takes to make the above tractable, reproducible, and defensible when someone who actually studies this looks at it.'],
];

const D = [
/* --------------------------------------------------------------- time -- */
{c:'time',t:'Anchor the clock to the real timescale',k:'clock',d:'Fix t=0 at 4.567 Ga (the CAI age) and let the run reach the present. The prototype’s flat 200 years per tick means a 4.5-billion-year history costs 22 million ticks; nothing about the pacing survives contact with the actual numbers until this is fixed.',x:'SIM',e:'M',i:3},
{c:'time',t:'Adaptive tick length, log-scaled',k:'logtime',n:['clock'],d:'Ten million years per tick through the Hadean, a hundred thousand through the Phanerozoic, ten through the Holocene. The tick is a rendering decision about how fast the interesting variable is changing, and should be derived from the maximum rate of change across the field set.',x:'SIM',e:'M',i:3},
{c:'time',t:'The ICS chart as a real subdivided ribbon',k:'chart',n:['clock'],d:'Eon, era, period, epoch, age — nested, with Earth’s canonical boundaries on one side and your planet’s independently derived ones on the other. Watching your own Cambrian land 90 Myr late is the whole product in one image.',x:'BOTH',e:'M',i:3},
{c:'time',t:'Name eras from state transitions, not a timer',n:['chart'],d:'`maybeNameEra` currently fires every 48,000 years and picks from eight strings. Boundaries in the real chart are defined by events in rock: a first appearance, an isotope excursion, an extinction horizon. Derive the boundary from the event and the name from what dominated between them.',x:'SIM',e:'M',i:3},
{c:'time',t:'The Hadean as a playable opening, not a skipped warmup',n:['clock'],d:'Magma ocean, a Moon-forming impact at ~4.51 Ga, a crust that repeatedly resets, and the Jack Hills zircons at 4.4 Ga arguing that liquid water arrived far earlier than anyone expected. `generate()` currently runs 24 silent warmup ticks with life paused; that is four hundred million years of the best story on the planet, hidden.',x:'BOTH',e:'M',i:3},
{c:'time',t:'Late bombardment as a contested option',n:['clock'],d:'The terminal cataclysm at 3.9 Ga is no longer consensus — the lunar sample ages that motivated it may be a single Imbrium artefact. Ship both: a spiky declining flux and a smooth one, labelled as the open question it is.',x:'SIM',e:'S',i:1},
{c:'time',t:'The faint young Sun',k:'faint',n:['clock'],d:'The Sun was about 70% as luminous at 4 Ga and brightens roughly 1% per 110 Myr. Earth was not frozen, which is the paradox that Daisyworld exists to answer. Wire luminosity to age and the greenhouse has to do real work to keep the Archean liquid.',x:'SIM',e:'S',i:3},
{c:'time',t:'Respect the proportions — 88% of it is microbial',n:['logtime'],d:'From first life to the Cambrian is roughly 3.1 Gyr; everything with a skeleton fits in the last 12% of the record. The temptation is to compress the boring part. Do the opposite: make the microbial world worth watching (see the metabolism category) and let its duration land.',x:'BOTH',e:'M',i:3},
{c:'time',t:'The Boring Billion, deliberately',n:['logtime'],d:'From ~1.8 to ~0.8 Ga the isotope record is famously flat: mid-range oxygen, sulfidic mid-depth oceans, phosphorus scarcity, and eukaryotes present but going nowhere. Model the stasis as a stable attractor the player can be trapped in rather than a gap in the content.',x:'SIM',e:'M',i:2},
{c:'time',t:'Day length as an evolving quantity',n:['clock'],d:'The Moon recedes about 3.8 cm a year and the Earth day has grown from perhaps 6 hours to 24. Rotation is already a ruleset parameter driving Coriolis; letting it drift over the run changes circulation, tides and the diurnal temperature swing on a schedule you can read in tidal rhythmites.',x:'SIM',e:'S',i:2},
{c:'time',t:'Auto-captured moments at every first occurrence',n:['chart'],d:'First cell, first photosynthesis, first oxygen, first eukaryote, first multicellular body, first land plant, first flower, first frost after the last one. Capture a camera pose, a field snapshot and a timestamp so the run can be scrubbed by event rather than by year.',x:'BOTH',e:'M',i:3},
{c:'time',t:'Rewind the tape of life',n:['chart'],d:'Gould’s thought experiment, made mechanical: pick a date, fork the run with a different RNG stream, and let the player watch two histories diverge from an identical planet. This is the single most persuasive demonstration that the simulation is generative rather than scripted.',x:'BOTH',e:'L',i:3},

/* -------------------------------------------------------------- metab -- */
{c:'metab',t:'Rebuild the biosphere on a redox tower',k:'redox',d:'Replace `LIFE_CLASSES` with metabolic guilds ordered by the reduction potential of the half-reactions they run. A guild is viable in a cell when its donor and acceptor are both present and the free energy yield clears a maintenance threshold; when the last cell running a pathway dies, the pathway is gone until something reinvents it. This one change turns the first three billion years from a waiting room into the main event, and it gives the chemistry a memory.',x:'SIM',e:'L',i:3},
{c:'metab',t:'Track the electron donors and acceptors as fields',k:'species',n:['redox'],d:'H₂, H₂S, Fe²⁺, CH₄, NH₄⁺, organic carbon on the donor side; O₂, NO₃⁻, SO₄²⁻, Fe³⁺, CO₂ on the acceptor side. Ten scalar fields, and every microbial story in Earth history is a competition between them for the same electrons.',x:'SIM',e:'M',i:3},
{c:'metab',t:'Growth yield from actual free energy',n:['species'],d:'ΔG for each reaction under local concentration and temperature, converted to a growth yield. Aerobic respiration of glucose releases roughly 2,870 kJ/mol against about 130 for methanogenesis from H₂ and CO₂ — a twenty-fold difference that explains why the world changed shape once oxygen existed.',x:'SIM',e:'M',i:3},
{c:'metab',t:'Chemolithoautotrophy first',n:['redox'],d:'Serpentinization of olivine at hydrothermal systems produces H₂ abiotically and continuously. Seed the first guild at vent cells — which the code already flags via `bound[c] === 0` — and let it be genuinely independent of sunlight, because the first biosphere was.',x:'SIM',e:'M',i:3},
{c:'metab',t:'Methanogens and the Archean haze',n:['species','faint'],d:'A methanogen-dominated ocean pushes atmospheric CH₄ to perhaps 1,000 ppm, and above a C/O ratio near 1 the photochemistry produces a Titan-like organic haze that is an *anti*-greenhouse. A biosphere that warms its planet, then veils it, then cools it — Gaia’s first real argument with itself.',x:'BOTH',e:'M',i:3},
{c:'metab',t:'Anoxygenic photosynthesis, in its proper place',n:['species'],d:'Purple and green sulfur bacteria split H₂S rather than H₂O, produce elemental sulfur rather than oxygen, and almost certainly came first because the chemistry is far easier. Give them a few hundred million years of dominance and the surface should be visibly not-green.',x:'BOTH',e:'M',i:3},
{c:'metab',t:'Oxygenic photosynthesis as a single hard invention',k:'oxyphoto',n:['species'],d:'Splitting water requires the Mn₄CaO₅ cluster and a redox potential no other biological reaction reaches. As far as anyone can tell it evolved exactly once, in the cyanobacterial stem lineage. Make it a low-probability event with real preconditions, so that some runs never get oxygen and are correct not to.',x:'SIM',e:'M',i:3},
{c:'metab',t:'Aerobic respiration and the energy budget for being big',n:['oxyphoto'],d:'Roughly sixteen times the ATP yield of fermentation. Every subsequent constraint on body size, activity level and nervous tissue traces back to this number, which is why the existing `minO2` thresholds are right in spirit and arbitrary in value.',x:'SIM',e:'M',i:3},
{c:'metab',t:'Nitrogen fixation, and the fact that nitrogenase hates oxygen',n:['species'],d:'Breaking the N≡N triple bond costs 16 ATP per molecule and the enzyme that does it is irreversibly poisoned by O₂. The resulting engineering problem — heterocysts, root nodules, nocturnal fixation — is one of biology’s great compromises and a genuine limiter on productivity.',x:'SIM',e:'M',i:2},
{c:'metab',t:'Close the nitrogen cycle: nitrification, denitrification, anammox',n:['species'],d:'Fixed nitrogen returns to N₂ through anaerobic pathways, so the ocean’s nitrogen inventory is a balance between two microbial guilds rather than a stock. This is what makes nitrogen the *proximate* limiter on marine productivity while phosphorus remains the ultimate one.',x:'SIM',e:'M',i:2},
{c:'metab',t:'Sulfate reduction and the Canfield ocean',n:['species'],d:'Once surface oxidation supplies sulfate, sulfate reducers make the mid-depth ocean euxinic — sulfidic, not merely anoxic. Canfield’s model explains the Boring Billion’s trace-metal famine, which in turn starves nitrogenase, which in turn caps productivity. A three-link causal chain the player can watch.',x:'SIM',e:'M',i:2},
{c:'metab',t:'Iron oxidation and banded iron formations',n:['species'],d:'The Archean ocean held dissolved Fe²⁺ because there was no oxygen to precipitate it. Photoferrotrophs and, later, free O₂ dropped it out as alternating iron and chert bands. Deposit these as an actual rock type in the existing `rock` layer so the player can core them later.',x:'BOTH',e:'M',i:3},
{c:'metab',t:'Fermentation as the universal fallback',n:['redox'],d:'Wherever acceptors run out, life ferments — low yield, no external acceptor, always available. It is the floor of the redox tower and it guarantees that anoxic cells are never simply dead, which matters enormously for how a snowball or a euxinic basin looks.',x:'SIM',e:'S',i:2},
{c:'metab',t:'Microbial mats and stromatolites as terrain',n:['redox'],d:'Laminated mats are the dominant *visible* life form for two and a half billion years, they build carbonate structures metres high, and they are the reason the Archean shoreline has texture at all. They also make the strongest possible case that the microbial era is worth rendering.',x:'BOTH',e:'M',i:3},
{c:'metab',t:'Syntrophy — guilds that only work in pairs',n:['redox'],d:'Anaerobic methane oxidation runs as an archaeal–bacterial consortium; neither partner is viable alone because the reaction is only exergonic when the product is immediately consumed. Model a few obligate pairs and cooperation stops being a late-game civilisation mechanic and becomes a founding one.',x:'SIM',e:'M',i:2},
{c:'metab',t:'Surface colour from pigment chemistry',n:['redox'],d:'Bacteriochlorophyll a peaks near 800 nm, chlorophyll a at 430 and 662, carotenoids in the blues, phycoerythrin in the greens. Drive the `land()` and `ocean()` colour functions from the dominant guild’s absorption spectrum instead of a green ramp keyed to `life[c]`.',x:'EYE',e:'M',i:3},

/* -------------------------------------------------------------- trans -- */
{c:'trans',t:'Model the major transitions explicitly',k:'trans',d:'Eight or so changes in how information is stored, transmitted and divided: replicators to chromosomes, RNA to DNA and protein, prokaryote to eukaryote, asexual to sexual, single cells to multicellular bodies, solitary to eusocial, and primate societies to language. Each is a gate with preconditions, a probability, and permanent consequences.',x:'SIM',e:'L',i:3},
{c:'trans',t:'Abiogenesis as a probability, not a start condition',k:'origin',n:['trans'],d:'A per-cell, per-interval chance modulated by the presence of a redox gradient, a mineral surface, a wet–dry cycle and a temperature band. Some worlds should simply never light up. A god-game where life is guaranteed has quietly answered the most interesting question in the room.',x:'SIM',e:'M',i:3},
{c:'trans',t:'RNA world and the error threshold',n:['origin'],d:'Eigen’s limit: a replicator cannot maintain more information than roughly the inverse of its per-base error rate. This is a real, hard ceiling that only a proofreading polymerase escapes, and it is why the RNA-to-DNA transition had to happen before anything complex could.',x:'SIM',e:'M',i:2},
{c:'trans',t:'LUCA as an actual node',k:'luca',n:['origin'],d:'Not a metaphor — the root of the live phylogeny, dated in your world’s own time, with a reconstructible trait set. Everything alive descends from it and the tree tool should be able to walk you back there from any leaf.',x:'BOTH',e:'M',i:3},
{c:'trans',t:'The bacteria–archaea divergence',n:['luca'],d:'Different membrane lipids, different cell walls, different replication machinery — the deepest split in the tree and the one that makes the later eukaryotic merger so strange. Two domains with genuinely different tolerance envelopes gives the early world real biogeography.',x:'SIM',e:'M',i:2},
{c:'trans',t:'The mitochondrion: one merger, everything after',k:'euk',n:['luca','oxyphoto'],d:'An archaeal host acquires a bacterial endosymbiont, once, somewhere between 2.1 and 1.6 Ga. Lane and Martin’s argument is that this is what buys energy per gene, and therefore the genome size a complex cell requires. Make it singular, contingent, and the hardest gate in the run.',x:'SIM',e:'M',i:3},
{c:'trans',t:'Plastids, and then plastids again',n:['euk'],d:'A cyanobacterium is swallowed once to make the primary plastid; then that alga is swallowed again by other eukaryotes to make secondary and tertiary plastids, which is where diatoms, dinoflagellates and brown algae come from. Nested endosymbiosis explains why the ocean’s primary producers look nothing like a plant.',x:'SIM',e:'M',i:2},
{c:'trans',t:'Sex, and why it is worth the twofold cost',n:['euk'],d:'An asexual lineage out-reproduces a sexual one two to one, and yet recombination wins almost everywhere it appears. Model Muller’s ratchet — irreversible mutation accumulation in asexual lineages — and the cost pays for itself over deep time without needing to be asserted.',x:'SIM',e:'M',i:2},
{c:'trans',t:'Multicellularity, twenty-five separate times',k:'multi',n:['euk'],d:'It is not one invention. Complex multicellularity arose independently in animals, land plants, red algae, brown algae and several fungal lineages, each with different adhesion, signalling and division-of-labour solutions. Let different clades in your tree find it separately and differ afterwards.',x:'SIM',e:'M',i:3},
{c:'trans',t:'Eusociality as a rare, conditional transition',n:['multi'],d:'A handful of origins, clustered in haplodiploid lineages and in monogamous ones, where relatedness makes reproductive altruism pay. It is also the transition that most obviously prefigures civilisation, which makes it the right seam between the biosphere and the agent layer.',x:'SIM',e:'M',i:2},
{c:'trans',t:'Biomineralization and the Cambrian',n:['multi'],d:'Skeletons need oxygen for collagen synthesis, dissolved calcium and carbonate saturation, and a predator worth armouring against. The explosion is not a mystery so much as a threshold crossing in three variables at once — all three of which you already simulate.',x:'BOTH',e:'M',i:3},
{c:'trans',t:'Terrestrialization as a four-condition gate',n:['multi'],d:'Ozone shielding, a soil with enough organic matter to hold water, desiccation-resistant reproduction, and structural tissue that works without buoyancy. The existing `needUV` flag captures a quarter of this. The other three-quarters are the interesting part and produce a visibly staged colonisation of the coasts first.',x:'BOTH',e:'M',i:3},
{c:'trans',t:'Endothermy as its own axis',n:['multi'],d:'Roughly a tenfold increase in resting metabolic rate, bought for a wholly different set of temperature tolerances, activity budgets and food requirements. It is what lets a lineage survive a climate that kills its ectothermic competitors, and it should be a trait with a cost, not a rung labelled "mammal".',x:'SIM',e:'M',i:2},
{c:'trans',t:'Language and the last transition',n:['trans'],d:'Unlimited heritable information transmitted outside the genome. This is the seam where the civilisation layer in the main backlog attaches, and it should require a specific set of prior traits rather than appearing when a year counter clears a threshold.',x:'SIM',e:'M',i:2},

/* ------------------------------------------------------------- genome -- */
{c:'genome',t:'Give populations a heritable trait vector',k:'traits',d:'Retire `lifeClass` as a Uint8 index. A population carries a vector — thermal optimum and breadth, desiccation tolerance, O₂ affinity, body mass, dispersal distance, reproductive investment, trophic position, defence — and everything from tolerance envelopes to sprite morphology reads from it.',x:'SIM',e:'L',i:3},
{c:'genome',t:'Mutation with per-trait rates',n:['traits'],d:'Each trait gets its own mutational variance, because they genuinely differ: pigment shifts easily, body plan does not. Mutation–selection balance then sets standing variation without anyone tuning a diversity number by hand.',x:'SIM',e:'M',i:3},
{c:'genome',t:'Genetic drift scaled by effective population size',n:['traits'],d:'Small isolated populations lose variation and fix deleterious alleles fast; large ones are dominated by selection. Since your cells already carry a carrying capacity, Ne comes almost free, and it is what makes island lineages weird rather than merely rare.',x:'SIM',e:'M',i:2},
{c:'genome',t:'Fisher’s geometric model for adaptation',n:['traits'],d:'Fitness as distance from a moving local optimum in trait space; large mutations are usually bad, small ones are a coin flip, and adaptation shows diminishing returns as the optimum is approached. It is three lines of vector maths and it produces recognisably real adaptive dynamics.',x:'SIM',e:'M',i:2},
{c:'genome',t:'Allopatric speciation from actual barriers',k:'spec',n:['traits'],d:'Detect connected components of habitable cells for a given population, and when gene flow between two components drops below a threshold for long enough, split the lineage. Your tectonics already builds and destroys the barriers; this wires the two together.',x:'SIM',e:'M',i:3},
{c:'genome',t:'Sympatric and ecological speciation',n:['spec'],d:'Divergent selection along a resource axis inside a single range, with assortative mating as the reinforcing step. Rarer than allopatry and more interesting when it happens, particularly in lakes and on the reef cells you already track.',x:'SIM',e:'M',i:2},
{c:'genome',t:'A live phylogenetic tree as a first-class object',k:'tree',n:['spec'],d:'Nodes with birth dates, parents, trait vectors at divergence, and extinction dates. Every question the player wants to ask — what is this, where did it come from, what killed its cousins — is a query against this structure, and it must exist before any of them can be answered.',x:'SIM',e:'M',i:3},
{c:'genome',t:'Molecular clock in your world’s own time',n:['tree'],d:'Accumulate neutral substitutions at a constant rate so branch lengths are measured in changes as well as years. It gives the phylogeny instrument a second, independent axis and lets the player discover that the two disagree — which is exactly the argument real systematists have.',x:'SIM',e:'S',i:2},
{c:'genome',t:'Extinction prunes the branch but keeps the ghost',n:['tree'],d:'A dead clade stays in the tree with a terminal date, so the diversity curve, the fossil record and the "what used to live here" query all remain answerable. Deleting extinct lineages is the single easiest way to make deep time feel weightless.',x:'SIM',e:'S',i:3},
{c:'genome',t:'Generated clade names with etymology',n:['tree'],d:'Stable, pronounceable, and derived from the traits that defined the clade at divergence, so the name tells you something. The existing entity namer produces two-syllable mush; a clade needs a name a player will still recognise four hundred million simulated years later.',x:'BOTH',e:'M',i:2},
{c:'genome',t:'Detect and flag convergent evolution',n:['tree'],d:'When two distant branches occupy the same region of trait space, say so. Ichthyosaurs and dolphins, or the fifty-odd independent origins of the eye, are the strongest evidence that the search is finding real optima rather than wandering — and the player should be told when it happens.',x:'BOTH',e:'M',i:3},
{c:'genome',t:'Adaptive radiation into empty niche space',n:['tree'],d:'After an extinction or a colonisation, the rate of speciation should spike and then decay as niches fill. This produces the characteristic burst-then-plateau shape of every real radiation, from Cambrian arthropods to Hawaiian honeycreepers.',x:'SIM',e:'M',i:3},
{c:'genome',t:'Let punctuated equilibrium be an outcome, not an assumption',n:['tree'],d:'If speciation is concentrated at range fragmentation events and stasis dominates between them, Eldredge and Gould’s pattern falls out of the mechanism. Do not hard-code either tempo; measure which one your world produced and show the player the answer.',x:'SIM',e:'M',i:2},
{c:'genome',t:'Horizontal gene transfer among microbes',n:['tree'],d:'For prokaryotes the tree is a poor model — genes move sideways, especially metabolic ones. Implement a trait market with a distance and abundance cost, and the early phylogeny becomes a web, which is both more accurate and visually a completely different object.',x:'SIM',e:'M',i:2},
{c:'genome',t:'Developmental constraint and evolvability',n:['traits'],d:'Some traits become locked once a body plan is committed — no tetrapod has ever re-evolved a sixth limb. Model a hardening of certain trait axes with clade age, so that lineages accumulate history and cannot simply reconverge on any optimum.',x:'SIM',e:'M',i:2},
{c:'genome',t:'A complexity ratchet with an energy price',n:['euk'],d:'Genome size, cell size and trait count can rise, but each increment costs maintenance energy that must be paid every tick. Complexity should be an investment that a poor environment cannot afford, which is the honest reason most of the biosphere is still single-celled.',x:'SIM',e:'M',i:2},

/* ---------------------------------------------------------------- eco -- */
{c:'eco',t:'Net primary productivity from a real model',k:'npp',d:'`carryingCapacity()` multiplies insolation by water by nutrients and clamps to 0.55. Replace it with light-use efficiency against absorbed radiation, limited by temperature and water — Monteith’s formulation, or the Miami model as a cheaper first pass. NPP is the currency every other ecological item spends.',x:'SIM',e:'M',i:3},
{c:'eco',t:'Trophic pyramids from transfer efficiency',n:['npp'],d:'About 10% of the energy at one trophic level reaches the next. Four levels therefore cost three orders of magnitude, which is why apex predators are rare, why they go extinct first, and why an ecosystem cannot have five of them. Arithmetic, not balancing.',x:'SIM',e:'M',i:3},
{c:'eco',t:'The food web as an object with links',n:['npp','traits'],d:'Two global scalars — `herbivore` and `carnivore` — currently stand in for every trophic relationship on the planet. A sparse link matrix between populations, weighted by body-size ratio and encounter rate, gives you cascades, keystones and secondary extinctions for free.',x:'SIM',e:'L',i:3},
{c:'eco',t:'Type II and III functional responses',n:['npp'],d:'Predator intake saturates with prey density because handling takes time, and switches when alternative prey is available. Naive Lotka–Volterra oscillates forever; a saturating response gives you the stable coexistence and the sudden collapses that real systems show.',x:'SIM',e:'M',i:2},
{c:'eco',t:'Kleiber’s law',k:'kleiber',n:['traits'],d:'Metabolic rate scales as mass to the three-quarter power, so population density scales as mass to the minus three-quarters and lifespan scales as mass to the quarter. Three of the most robust patterns in biology, from one exponent, and they set how many of anything can be alive at once.',x:'SIM',e:'S',i:3},
{c:'eco',t:'Temperature-dependent metabolic rates',n:['kleiber'],d:'Rates scale with an Arrhenius term near 0.65 eV, which means a 10 °C warming roughly doubles metabolic demand. This is why warming oceans lose large animals first and why the tropics have fast turnover — and it couples the biosphere to the climate model in the right direction.',x:'SIM',e:'M',i:2},
{c:'eco',t:'Body size limited by oxygen and gravity',n:['kleiber'],d:'Carboniferous dragonflies with 70 cm wingspans needed ~30% atmospheric O₂ because insect tracheae are diffusion-limited. `W.bodyScale` already gestures at this with a linear O₂ term; make it a real diffusion and support-strength constraint that differs between body plans and gravities.',x:'BOTH',e:'M',i:3},
{c:'eco',t:'Redfield stoichiometry',k:'redfield',n:['npp'],d:'Marine plankton hold carbon, nitrogen and phosphorus at close to 106:16:1, which means the ocean’s productivity is set by whichever element runs out first relative to that ratio. It is the tightest coupling between biology and chemistry anywhere in the system.',x:'SIM',e:'M',i:2},
{c:'eco',t:'Nitrogen limits the season, phosphorus limits the eon',n:['redfield'],d:'Fixed nitrogen can be replenished biologically in years; phosphorus comes only from rock weathering and leaves only by burial, on million-year timescales. Model both and the biosphere has a fast throttle and a slow ceiling, which is exactly what the record shows.',x:'SIM',e:'M',i:3},
{c:'eco',t:'Upwelling as the ocean’s productivity map',n:['redfield'],d:'Wind-driven divergence at eastern boundaries and the equator brings deep nutrients to the surface. Fewer than 1% of ocean cells produce a disproportionate share of the fish, and the pattern is derivable from the wind field the atmosphere already computes.',x:'BOTH',e:'M',i:3},
{c:'eco',t:'Keystone species and trophic cascades',n:['npp'],d:'Removing one predator can restructure an entire community — Paine’s starfish, the sea otter and the kelp forest, the wolves of Yellowstone. Make the effect emergent from the link matrix so that the player’s casual extinction has consequences three steps away.',x:'SIM',e:'M',i:2},
{c:'eco',t:'Ecosystem engineers that rewrite their own habitat',n:['npp'],d:'Corals build reefs, trees build soil and shade, earthworms build the top metre of every temperate landscape. The prototype already has settlers raising `build[c]`; the same mechanism belongs to organisms a billion years earlier, and it is what makes a biosphere a geological force.',x:'BOTH',e:'M',i:3},
{c:'eco',t:'Herbivory as a coevolutionary arms race',n:['traits'],d:'Plant chemical defence against herbivore detoxification, each escalating, each costly. It is a legible two-trait Red Queen dynamic and it explains a large fraction of terrestrial chemistry — including most of what humans later call medicine.',x:'SIM',e:'M',i:2},
{c:'eco',t:'Decomposers as a required guild',n:['npp'],d:'When nothing could digest lignin, Carboniferous plant matter buried instead of rotting, oxygen climbed toward 35%, and the world caught fire regularly. Make decomposition a guild that can be absent, and one of Earth’s strangest 60-million-year intervals becomes reachable.',x:'SIM',e:'M',i:3},

/* ------------------------------------------------------------- biogeo -- */
{c:'biogeo',t:'Whittaker biome classification',k:'biome',d:'Classify each land cell by mean annual temperature and precipitation against Whittaker’s diagram: tundra, boreal, temperate deciduous, temperate rainforest, grassland, desert, savanna, tropical seasonal, tropical rainforest. The current `land()` functions approximate this with four hand-tuned branches; deriving it gives coherent, arguable biomes.',x:'BOTH',e:'M',i:3},
{c:'biogeo',t:'The latitudinal diversity gradient, emergent',n:['biome','tree'],d:'More species at the equator than at the poles is the oldest pattern in ecology and its cause is still contested — more energy, more time, more area, or faster speciation. Do not impose it; measure whether your world produced it, and let the player argue with the result.',x:'SIM',e:'M',i:3},
{c:'biogeo',t:'The species–area relationship',n:['tree'],d:'Species count scales as area to roughly the 0.25 power. It is what makes habitat fragmentation lethal, and it gives a principled way to report diversity per region rather than a single global number.',x:'SIM',e:'S',i:1},
{c:'biogeo',t:'Island biogeography as an equilibrium',n:['spec'],d:'MacArthur and Wilson: species richness settles where immigration from the mainland balances local extinction, so richness rises with island size and falls with distance. Every archipelago your hotspot chains produce should independently reproduce this.',x:'SIM',e:'M',i:2},
{c:'biogeo',t:'Vicariance: let the plates split the lineages',n:['spec'],d:'When a rift opens through a range, the population divides and diverges. Your tectonics already does continental breakup; connecting it to speciation means the phylogeny and the plate reconstruction tell the same story, which is precisely how real biogeography was discovered.',x:'SIM',e:'M',i:3},
{c:'biogeo',t:'Dispersal barriers and sweepstakes routes',n:['spec'],d:'Wallace’s Line runs between Bali and Lombok through 35 km of deep water and separates two entirely different faunas. Model rare, chance long-distance dispersal separately from ordinary range expansion, because the rare events are what put mammals on Madagascar.',x:'SIM',e:'M',i:2},
{c:'biogeo',t:'Faunal interchange when land bridges form',n:['spec'],d:'The Isthmus of Panama closed around 3 Ma and two continents’ mammals invaded each other, with lopsided results. A land bridge is a topological event in a heightfield you already recompute every tick; the biological consequence is dramatic and free.',x:'SIM',e:'M',i:2},
{c:'biogeo',t:'Glacial refugia and bottleneck signatures',n:['spec'],d:'Ranges collapse to a few pockets during glaciations and re-expand after, leaving reduced diversity and a signature in the molecular clock. It is the mechanism that connects your Milankovitch cycles to your phylogeny.',x:'SIM',e:'M',i:2},
{c:'biogeo',t:'Endemism, and how fragile it is',n:['spec'],d:'Isolated lineages are unique, often flightless, often naive about predators, and reliably the first casualties of any connection event. This is where a god-game’s casual gesture — one land bridge, one introduced species — has its most affecting consequence.',x:'BOTH',e:'M',i:2},
{c:'biogeo',t:'Altitudinal zonation',n:['biome'],d:'A thousand metres of elevation is worth roughly a thousand kilometres of latitude. The lapse rate is already in `atmoTick`; letting biomes stack up a mountainside gives every range a banded structure that reads instantly from orbit.',x:'BOTH',e:'S',i:3},
{c:'biogeo',t:'Ocean biogeography, not just ocean colour',n:['npp'],d:'Subtropical gyres are deserts, boundary currents are highways, the deep sea is a single vast cold province and hydrothermal vents are islands with their own endemics. The ocean is 71% of the surface and currently has one biome.',x:'BOTH',e:'M',i:3},
{c:'biogeo',t:'Range shifts and extinction debt under climate change',n:['biome'],d:'Species track their climate envelope poleward and upslope until they run out of continent or mountain. The lag between the climate moving and the extinction landing is decades to millennia, and rendering that lag is what makes a warming trend legible as loss.',x:'BOTH',e:'M',i:3},
{c:'biogeo',t:'Biome bistability and hysteresis',n:['biome'],d:'Forest and savanna are alternative stable states over a wide rainfall band because trees make their own rain; boreal forest and tundra likewise, through albedo. Once you can flip a biome and not flip it back, the map has memory.',x:'SIM',e:'M',i:3},

/* ------------------------------------------------------------ extinct -- */
{c:'extinct',t:'Separate background from mass extinction',k:'ext',n:['tree'],d:'Background extinction is a roughly constant per-lineage hazard; a mass extinction is a statistically detectable excursion above it. Measure the rate rather than scripting the events, so a player-caused catastrophe is scored on the same scale as Chicxulub.',x:'SIM',e:'M',i:3},
{c:'extinct',t:'The Great Oxidation as the first mass extinction',n:['ext','oxyphoto'],d:'Free oxygen is a poison to obligate anaerobes and it appeared everywhere at once. The prototype has an oxygenation event that multiplies life by 0.35; make it a selective kill against guilds lacking oxygen tolerance, which is both more accurate and more interesting to survive.',x:'SIM',e:'M',i:3},
{c:'extinct',t:'End-Ordovician: ice, then no ice',n:['ext'],d:'Roughly 445 Ma, glaciation on Gondwana drops sea level and drains the shallow shelves where almost everything lived, then deglaciation drowns them and brings anoxic water up. Two pulses, opposite in sign, about 85% of species gone.',x:'SIM',e:'M',i:2},
{c:'extinct',t:'Late Devonian: the plants did it',n:['ext'],d:'Deep-rooting land plants accelerate weathering, flush nutrients to the sea, cause eutrophication and widespread anoxia, and draw down CO₂ enough to cool the planet. The first time a biosphere nearly killed itself by succeeding, and a direct rehearsal of the argument the player will later have about their own civilisation.',x:'SIM',e:'M',i:3},
{c:'extinct',t:'End-Permian, with the full kill chain',n:['ext'],d:'Siberian Traps volcanism at ~252 Ma cooks coal beds, releases CO₂ and methane, warms the tropics past thermal tolerance, deoxygenates the ocean, turns the mid-depths euxinic and acidifies the surface. About 81% of marine species. Every link in that chain is a system you already have.',x:'SIM',e:'M',i:3},
{c:'extinct',t:'End-Triassic and ocean acidification',n:['ext'],d:'The Central Atlantic Magmatic Province erupts as Pangaea rifts, CO₂ spikes, and carbonate-shelled organisms fail preferentially because saturation state collapses faster than temperature rises. Acidification needs to be a separate variable from warming to tell this story at all.',x:'SIM',e:'M',i:2},
{c:'extinct',t:'K–Pg: the impact, the winter, and the traps',n:['ext'],d:'A 10-km bolide at Chicxulub, 66 Ma, ejecta reentry heating, a global impact winter lasting years, and the Deccan Traps erupting through the same interval. `applyImpact` already dusts the atmosphere; add the ejecta layer as a deposited rock unit the player can find later, because that iridium anomaly is how we know.',x:'BOTH',e:'M',i:3},
{c:'extinct',t:'Recovery takes millions of years',n:['ext'],d:'Full ecosystem complexity returns 5–10 Myr after a major extinction, not immediately. Model a recovery interval during which productivity is low and trophic structure is truncated, or extinctions become weightless setbacks rather than the hinges of the record.',x:'SIM',e:'M',i:3},
{c:'extinct',t:'Disaster taxa inherit the world first',n:['ext'],d:'Lystrosaurus made up most of the terrestrial vertebrate biomass after the Permian; fern spores dominate the first metre above the K–Pg boundary. Generalists with high reproductive rates bloom into the emptiness before anything else recovers, and it is one of the most visually distinctive intervals available.',x:'BOTH',e:'M',i:3},
{c:'extinct',t:'Every extinction names its own kill mechanism',n:['ext'],d:'The chronicle currently logs "Biosphere dieback" with a magnitude. It should log which variable crossed which threshold for which guild — thermal, hypoxic, acidification, UV, starvation, habitat loss. Attribution is what turns a graph into an explanation.',x:'BOTH',e:'M',i:3},
{c:'extinct',t:'Signor–Lipps: make the record imperfect on purpose',n:['ext'],d:'Because fossilisation is sporadic, a sudden extinction always looks gradual in the rock. If the player’s instruments read the preserved record rather than the true state, they inherit the actual epistemological problem of palaeontology — and that is a far better lesson than a perfect readout.',x:'BOTH',e:'M',i:2},
{c:'extinct',t:'Extinction debt and delayed collapse',n:['ext'],d:'A population below its minimum viable size is already gone, it just has not finished. Modelling the lag means the player’s intervention can be past the point of rescue while everything still looks alive, which is the most important thing this genre can teach.',x:'SIM',e:'M',i:3},

/* --------------------------------------------------------------- chem -- */
{c:'chem',t:'Split carbon into organic and inorganic reservoirs',k:'carbon',d:'Atmosphere, ocean dissolved inorganic carbon, living biomass, soil carbon, marine sediment, and rock. `gases.CO2` is currently the only carbon in the model, adjusted by two magic constants in `bioTick`. Every biogeochemical story below needs this partition first.',x:'SIM',e:'M',i:3},
{c:'chem',t:'Oxygen comes from burial, not photosynthesis',n:['carbon','oxyphoto'],d:'Photosynthesis and respiration cancel almost exactly. Free O₂ accumulates only to the extent that organic carbon is buried before it can be re-oxidised. This is the single most commonly misunderstood fact in Earth-system science and getting it right restructures the whole atmosphere model.',x:'SIM',e:'M',i:3},
{c:'chem',t:'The Great Oxidation with its real mechanism',n:['carbon'],d:'Between about 2.45 and 2.0 Ga, oxygen rises once the reduced sinks — dissolved iron, volcanic gases, sulfide — are overwhelmed. The disappearance of mass-independent sulfur isotope fractionation is the actual evidence, and it is a beautiful thing to hand a player as a readout.',x:'BOTH',e:'M',i:3},
{c:'chem',t:'The Lomagundi excursion and the crash after it',n:['carbon'],d:'The largest carbon isotope excursion in Earth history, around 2.2–2.1 Ga, followed by an oxygen collapse. Deep time is not a ramp; it overshoots and falls back, and this is the clearest example.',x:'SIM',e:'M',i:2},
{c:'chem',t:'The Neoproterozoic Oxygenation Event',n:['carbon'],d:'A second rise around 800–540 Ma, closely bracketing the Snowball glaciations and immediately preceding animals. Whether oxygen enabled animals or animals enabled oxygen is still argued; model both couplings and let the run pick.',x:'SIM',e:'M',i:2},
{c:'chem',t:'Banded iron formations end when the sink is spent',n:['carbon'],d:'They stop forming around 1.8 Ga because the ocean’s dissolved Fe²⁺ is finally exhausted. A rock type that appears, persists for a billion years, and then never forms again — the strongest possible evidence that a planet has irreversible chapters.',x:'BOTH',e:'S',i:2},
{c:'chem',t:'Phosphorus as the ultimate limiting nutrient',n:['redfield'],d:'It has no gaseous phase, arrives only by weathering, and leaves only by burial. Over million-year timescales phosphorus availability sets the ceiling on the entire biosphere, which is why continental configuration and mountain building quietly control productivity.',x:'SIM',e:'M',i:3},
{c:'chem',t:'The silicate weathering thermostat, properly',k:'therm',n:['carbon'],d:'Walker, Hays and Kasting: weathering rate rises with temperature and runoff, drawing down CO₂ and cooling the planet, on a 100 kyr–1 Myr timescale. `gaiaTick` has this as one line with a magic 0.0000004. Give it explicit temperature and runoff dependence and it becomes the negative feedback that keeps a planet habitable for four billion years.',x:'SIM',e:'M',i:3},
{c:'chem',t:'Land plants change the thermostat’s gain',n:['therm'],d:'Roots, mycorrhizae and organic acids accelerate silicate weathering by perhaps an order of magnitude. Around 400 Ma the planet’s thermostat gets a new gain constant, CO₂ falls, and the Carboniferous ice age follows. A step change in a control system, caused by biology.',x:'SIM',e:'M',i:3},
{c:'chem',t:'Close the carbonate–silicate cycle through subduction',n:['therm'],d:'Carbonate sediment rides down at trenches and returns as CO₂ from arc volcanoes on a 100 Myr loop. Your tectonics already classifies every boundary; connecting the two closes the longest feedback loop on the planet and makes plate tectonics a *climate* mechanism.',x:'SIM',e:'M',i:3},
{c:'chem',t:'The biological pump and the carbonate compensation depth',n:['redfield'],d:'Sinking organic matter and carbonate tests export carbon to the deep ocean; below a certain depth carbonate dissolves rather than accumulates. The CCD is a visible, mappable surface in your bathymetry and it moves when the ocean acidifies.',x:'SIM',e:'M',i:2},
{c:'chem',t:'Methane clathrates and PETM-style carbon release',n:['carbon'],d:'At the Paleocene–Eocene boundary, 56 Ma, thousands of gigatonnes of carbon entered the system in under 20,000 years and the planet warmed 5–8 °C. It is the closest geological analogue to the present and it recovers over 150,000 years, which is the number that matters.',x:'SIM',e:'M',i:3},
{c:'chem',t:'Ocean acidification as its own variable',n:['carbon'],d:'Track surface pH and carbonate saturation state separately from temperature. Warming and acidification are the same cause with different victims, and a model that conflates them cannot tell the End-Triassic story or the modern one.',x:'SIM',e:'M',i:3},
{c:'chem',t:'Coal and oil as a one-time accident',n:['carbon'],d:'Most coal formed in a ~60 Myr Carboniferous window; most oil comes from two Cretaceous and Jurassic anoxic intervals. Deposit them where the model actually buries carbon, so a civilisation later finds fuel exactly where its own planet’s history put it, or does not find it at all.',x:'SIM',e:'M',i:3},
{c:'chem',t:'Isotope proxies as the player-facing evidence',k:'proxy',n:['carbon'],d:'δ¹³C for the organic carbon burial fraction, δ¹⁸O for ice volume and temperature, δ³⁴S for the sulfur cycle, ⁸⁷Sr/⁸⁶Sr for continental weathering. These are how the entire history above is actually known, and they turn every abstraction in this document into a line on a graph the player can read.',x:'BOTH',e:'M',i:3},

/* --------------------------------------------------------------- gaia -- */
{c:'gaia',t:'Demote Daisyworld from world to tutorial',d:'It is a two-species proof that regulation requires no foresight, and it has a flat featureless surface and no atmosphere because those would ruin the proof. As a selectable planet beside Europa and TRAPPIST-1 e it reads as a toy; as the opening five minutes that teach feedback before anything else, it is perfect.',x:'BOTH',e:'M',i:3},
{c:'gaia',t:'N-species Daisyworld with mutable albedo',d:'Lenton and Lovelock’s 2000 extension: let albedo mutate and the regulated temperature range widens dramatically, because the system keeps finding new species to do the job. It answers the standard objection to the original model and it is a small change to `daisyTick`.',x:'SIM',e:'S',i:2},
{c:'gaia',t:'Sequential selection, not planetary purpose',d:'The defensible version of Gaia is that unstable configurations are short-lived, so any planet you find has been running long enough to look regulated. Present regulation as survivorship rather than intent — the wording in the chronicle matters as much as the model.',x:'BOTH',e:'S',i:3},
{c:'gaia',t:'Tipping elements as named, tracked objects',k:'tip',d:'Lenton’s list: Greenland and West Antarctic ice, the Atlantic overturning circulation, Amazon dieback, boreal forest shift, permafrost carbon, coral reefs, monsoon systems. Each with a threshold, a hysteresis loop, and a timescale — and each already half-present in your hydro and bio code.',x:'SIM',e:'M',i:3},
{c:'gaia',t:'Rate of change, not just magnitude',n:['tip'],d:'Ecosystems survive climates they cannot survive arriving at. Make tolerance a function of dC/dt as well as C, and the difference between a slow natural excursion and a fast anthropogenic one becomes a mechanic rather than a talking point.',x:'SIM',e:'M',i:3},
{c:'gaia',t:'Separate habitability from inhabitance',d:'One number says the planet could support life; the other says it does. `W.health` currently blends them into a single orb colour. Splitting them lets the player face the genuinely unsettling case: a perfectly habitable world that is sterile, and has been for four billion years.',x:'BOTH',e:'S',i:3},
{c:'gaia',t:'Free-energy disequilibrium as the real biosignature',d:'The reason Earth is detectably alive from light-years away is that O₂ and CH₄ coexist in an atmosphere where they should react. Compute the thermodynamic disequilibrium of your gas mixture and you have a single scalar that means "something here is fighting entropy".',x:'SIM',e:'M',i:3},
{c:'gaia',t:'The Medea counterargument, playable',d:'Ward’s objection: life is more often suicidal than self-regulating — the oxygen catastrophe, the Devonian anoxia, the Permian, and now. Ship a ruleset where the biosphere reliably kills itself, and let the player discover which of the two hypotheses their own worlds keep supporting.',x:'SIM',e:'M',i:3},
{c:'gaia',t:'The Gaian bottleneck',d:'Chopra and Lineweaver’s proposal that most biospheres fail to establish regulation before their planet runs away, so the universe is full of brief, failed biospheres. As a distribution over the 120-world catalogue this becomes an empirical claim the player can test by playing.',x:'SIM',e:'M',i:2},
{c:'gaia',t:'Make regulation measurable',n:['tip'],d:'Report the actual feedback gain: how much the system opposes a given perturbation, and over what timescale. It replaces the health orb’s vibe with a number that has units, and it lets the player prove to themselves that their planet is or is not regulating.',x:'BOTH',e:'M',i:3},

/* -------------------------------------------------------------- alien -- */
{c:'alien',t:'Gate photosynthesis on photon flux in a usable band',k:'photons',d:'Oxygenic photosynthesis runs out of usable photons past roughly 750 nm. An M8 dwarf like TRAPPIST-1 emits most of its output beyond that, so the question is not whether the planet is warm enough but whether the light is energetic enough. Replace the temperature window with a photon budget.',x:'SIM',e:'M',i:3},
{c:'alien',t:'The red edge moves — or does not exist',n:['photons'],d:'Earth’s vegetation reflectance jumps at 700 nm because that is where chlorophyll stops absorbing. Under a redder star the edge should shift, or multi-photon schemes should appear, or photosynthesis should fail entirely. Whichever your model chooses, it should be visible in the surface colour and in the spectrum instrument.',x:'BOTH',e:'M',i:3},
{c:'alien',t:'The purple Earth hypothesis',n:['photons'],d:'Retinal-based phototrophy absorbs in the green and reflects red and blue, is simpler than chlorophyll, and may have come first. A retinal biosphere is magenta. It is scientifically defensible, visually unforgettable, and one line in the pigment table.',x:'BOTH',e:'S',i:3},
{c:'alien',t:'Biospheres with no light at all',k:'chemo',n:['redox'],d:'Serpentinization and radiolysis of water by potassium-40 and uranium decay supply hydrogen independent of any star. This is the energy source for a Europan ocean and for Earth’s own deep biosphere, and it means darkness is not the disqualifier it looks like.',x:'SIM',e:'M',i:3},
{c:'alien',t:'Ice-shell biospheres and their thin margin',n:['chemo'],d:'Europa’s tidal heating is of order 10¹² W across the whole moon, which sounds enormous and is not much once divided by an ocean. Model the energy budget honestly and the answer is a sparse, slow, deep biosphere — which is a genuinely different thing to render than a green planet.',x:'BOTH',e:'M',i:3},
{c:'alien',t:'Titan: a different solvent entirely',n:['chemo'],d:'Liquid methane at 94 K, with acetylene and hydrogen as the proposed redox couple, and roughly a thousandth of the energy density of aerobic metabolism. Everything is slower, smaller and colder, and the surface is already in your catalogue.',x:'SIM',e:'M',i:3},
{c:'alien',t:'An aerial biosphere in a Venusian cloud deck',n:['chemo'],d:'At 50 km altitude the temperature and pressure are Earth-like, though the droplets are concentrated sulfuric acid. Model a biosphere with no surface at all, and state the phosphine result as the contested, probably-refuted claim that it is.',x:'SIM',e:'M',i:2},
{c:'alien',t:'The deep continental biosphere',n:['chemo'],d:'Bacteria kilometres down in rock, with doubling times measured in centuries and a total mass comparable to everything on the surface. On any world with water and radiogenic heat, this is the biosphere most likely to exist — and it is invisible until the player drills.',x:'BOTH',e:'M',i:3},
{c:'alien',t:'Panspermia between bodies in one system',n:['origin'],d:'Impact ejecta carrying viable cells between neighbouring worlds. In a system view with several catalogue bodies, this is a link between two planets’ phylogenies — one tree, two worlds — which is a striking thing to be shown.',x:'SIM',e:'M',i:2},
{c:'alien',t:'Alternative chemistries, with their real problems stated',n:['chemo'],d:'Silicon polymers are unstable in water and their oxide is a solid rather than a gas; ammonia is liquid over a narrower range and at temperatures that slow every reaction. Ship them, and ship the objections alongside, because the objections are the interesting part.',x:'SIM',e:'M',i:1},
{c:'alien',t:'Sulfur ecosystems on volcanic worlds',n:['redox'],d:'On an Io analogue the surface chemistry is sulfur allotropes across a temperature range that paints the ground yellow, orange, red and black. Even without life it is a spectacular surface; with a sulfur-cycling guild it is a biosphere that looks like nothing on Earth.',x:'BOTH',e:'M',i:2},
{c:'alien',t:'Life that never leaves the water',n:['photons'],d:'Without oxygen there is no ozone, without ozone the land is sterilised by UV, and the biosphere stays marine indefinitely. This should be a common outcome, not a failure state, and the resulting world — blue, alive, and with bare continents — is one of the most beautiful things the engine can produce.',x:'BOTH',e:'M',i:3},
{c:'alien',t:'The terminator ring on a tidally locked world',n:['photons'],d:'On an eyeball planet the substellar point is too hot, the antistellar cap is frozen, and life occupies an annulus. It is the clearest possible demonstration that habitability is a place rather than a property of a planet.',x:'BOTH',e:'M',i:3},
{c:'alien',t:'Radiation-hardened biospheres',n:['chemo'],d:'Deinococcus survives doses thousands of times lethal to humans by repairing shattered chromosomes. Around a flare star or a pulsar, radiation tolerance becomes the dominant selective axis and the trait vector should reflect it.',x:'SIM',e:'M',i:2},
{c:'alien',t:'Let the dead worlds stay dead, and make that legible',d:'Most of the 120-world catalogue should never produce life, and the instruments should be able to say *why* — no solvent, no gradient, no time, too much flux. A null result that the player can interrogate is worth more than a biosphere that appears everywhere.',x:'BOTH',e:'M',i:3},

/* ------------------------------------------------------------ surface -- */
{c:'surface',t:'Physically based surface materials',k:'pbr',d:'Albedo, roughness and a spectral reflectance curve per material, rather than an RGB triple returned from a per-ruleset function. Once the surface has physical parameters, every lighting improvement below composes with it instead of fighting it.',x:'EYE',e:'L',i:3},
{c:'surface',t:'Real vegetation spectra',n:['pbr'],d:'Green leaves are only modestly green in the visible; what is dramatic is the jump to ~50% reflectance in the near infrared. Render the visible correctly and expose the NIR to the spectrum instrument, and you get both a better-looking planet and a working biosignature.',x:'EYE',e:'M',i:3},
{c:'surface',t:'The green wave — seasonal phenology',n:['pbr'],d:'Every spring a wave of leaf-out sweeps from the subtropics to the Arctic over about ten weeks, and every autumn it retreats. Your obliquity and seasons already exist; this is the single most alive-looking thing a planet does, and it is currently invisible.',x:'EYE',e:'M',i:3},
{c:'surface',t:'A snow line that migrates',d:'The seasonal snow boundary is the largest annual change in Earth’s albedo, sweeping tens of degrees of latitude. `ice[c]` is currently a threshold on temperature with no seasonal signal; animating it is cheap and it makes the whole climate system read as breathing.',x:'EYE',e:'M',i:3},
{c:'surface',t:'Sea ice with leads, polynyas and ridges',d:'Pack ice is not a white sheet — it is a fractured mosaic with open water between floes, and the open water is what dominates the heat exchange. The texture is distinctive enough that it identifies the material instantly from orbit.',x:'EYE',e:'M',i:2},
{c:'surface',t:'Ocean colour from what is actually in the water',n:['npp','pbr'],d:'Chlorophyll concentration, coloured dissolved organic matter and suspended sediment, each with a different spectral signature. Right now depth alone sets ocean colour; driving it from the biology means the player can see productivity from orbit, which is exactly how we see it on Earth.',x:'EYE',e:'M',i:3},
{c:'surface',t:'Sun glint',n:['pbr'],d:'The specular highlight on water, broadened by surface roughness into a bright patch tens of degrees across. It is the single cheapest cue that a surface is liquid, and it is how Cassini confirmed Titan’s lakes.',x:'EYE',e:'S',i:3},
{c:'surface',t:'Whitecaps and wind roughness',n:['pbr'],d:'Foam coverage scales with roughly the third power of wind speed, and it visibly brightens stormy ocean. The wind field is already computed per cell; this connects it to something the player can see without an overlay.',x:'EYE',e:'S',i:1},
{c:'surface',t:'Sediment plumes at river mouths',d:'`sediment[c]` is already tracked and already routed downstream. Rendering the plume where a river meets the sea gives every delta an ochre fan, and it is the visual proof that the erosion model is conserving mass.',x:'EYE',e:'S',i:3},
{c:'surface',t:'Reef bleaching you can watch happen',d:'The `reef[c]` field exists. Above about 1 °C over the local summer maximum for a few weeks, corals expel their symbionts and go bone white before they die. It is a colour change with a clear cause and a clear consequence, on a timescale the player experiences directly.',x:'BOTH',e:'S',i:3},
{c:'surface',t:'Displacement and parallax at close range',n:['pbr'],d:'The planet is a smooth sphere with a colour texture. At the Local tier the player is standing on it. Parallax-occlusion or real displacement for canopy, ridgelines and dunes is what makes the shrink-and-walk-in gesture pay off.',x:'EYE',e:'M',i:3},
{c:'surface',t:'Aeolian bedforms that follow the wind',d:'Barchans point downwind, longitudinal dunes align with it, yardangs are carved parallel to it. On Ares and every other dry world this turns the wind field into permanent, readable surface geometry rather than a transient dust field.',x:'EYE',e:'M',i:2},
{c:'surface',t:'Lava flows with cooling crusts',d:'Fresh basalt is near-black and cools through incandescent orange over days to weeks, and old flows weather to grey and then to red. Your volcanoes are already discrete objects with eruption schedules; giving their output an age and a colour ramp makes volcanic provinces legible for millions of years afterwards.',x:'EYE',e:'M',i:2},
{c:'surface',t:'Stratigraphy visible in canyon walls',n:['proxy'],d:'When a river cuts through the rock layers your own simulation deposited, the wall should show them — banded iron, the ejecta layer, the coal measures. This is the moment the geology stops being bookkeeping and becomes scenery with a story.',x:'BOTH',e:'M',i:3},
{c:'surface',t:'Procedural detail driven by the fields, not tiled noise',n:['pbr'],d:'Sub-cell texture should be generated from the local slope, moisture, rock type and biome rather than a repeating pattern. It keeps the close view honest — what you see at one metre is a consequence of the same numbers that drove the view from orbit.',x:'EYE',e:'M',i:2},
{c:'surface',t:'The night side, populated',d:'Lava glow, bioluminescent blooms, auroral curtains, lightning in storm cells, and eventually city lights. `uNight` currently brightens the dark hemisphere in proportion to `meanLife`, which is a placeholder for something that could be the most beautiful view in the product.',x:'EYE',e:'M',i:3},

/* ---------------------------------------------------------------- air -- */
{c:'air',t:'Precomputed physical atmospheric scattering',k:'scatter',d:'A Bruneton-style transmittance and multiple-scattering LUT with real Rayleigh and Mie coefficients, replacing the analytic rim term in the planet fragment shader. This is the highest-yield rendering change available and everything else in this category depends on it.',x:'EYE',e:'L',i:3},
{c:'air',t:'Ozone absorption in the Chappuis band',n:['scatter'],d:'The reason Earth’s twilight sky goes deep blue rather than fading through orange is ozone absorbing in the 500–700 nm range along a long slant path. You already derive an ozone proxy from O₂ — feeding it into the scattering model links a biological variable directly to the colour of the sky.',x:'EYE',e:'M',i:3},
{c:'air',t:'Aerosol optical depth from the dust and sulphate fields',n:['scatter'],d:'`gases.dust` and `gases.sulphate` currently subtract from the greenhouse term and tint the atmosphere constant. As a Mie scattering parameter they would redden the sun, wash out the horizon, and turn a volcanic winter into something you can see from orbit and from the ground.',x:'EYE',e:'M',i:3},
{c:'air',t:'Volumetric clouds with real types',n:['scatter'],d:'Cumulus over convective heating, stratus in stable marine air, cirrus at the tropopause, and the anvil of a mature storm. The cloud shell is currently a single translucent layer; typing it by local stability and height makes the atmosphere three-dimensional.',x:'EYE',e:'L',i:3},
{c:'air',t:'Cloud shadows',n:['scatter'],d:'On the surface and, at grazing angles, projected through the atmosphere itself. It is the cue that separates a cloud layer from a decal, and it also closes the albedo loop visually — the dark patch is where the surface is being cooled.',x:'EYE',e:'M',i:2},
{c:'air',t:'Cyclones with structure',d:'Spiral rainbands, a clear eye, an asymmetric wind field, and a track that curves poleward. The main backlog has cyclones as tracked objects at partial status; the rendering is what makes them the headline weather event they should be.',x:'EYE',e:'M',i:2},
{c:'air',t:'Auroral ovals',d:'Two rings offset toward the night side, at a magnetic latitude set by the field strength you already carry as `magnetosphere`, brightening with solar activity. It is the visible proof that the planet has a magnetic field, which is otherwise an invisible number that decides whether the atmosphere survives.',x:'EYE',e:'M',i:3},
{c:'air',t:'Airglow and the bright limb at night',n:['scatter'],d:'A thin green-orange band from recombining atomic oxygen at ~90 km, visible in every photograph taken from orbit. It costs almost nothing and it is one of the details that makes an image read as photographic rather than rendered.',x:'EYE',e:'S',i:1},
{c:'air',t:'An HDR pipeline with meaningful exposure',k:'hdr',d:'Radiance values in physical units, a tonemapping curve, and an exposure that means something. Without it, a world at 636,000× Earth’s insolation and one at 0.1× have to be authored to look different rather than simply being different.',x:'EYE',e:'M',i:3},
{c:'air',t:'Eye adaptation across the scale gesture',n:['hdr'],d:'Descending from orbit into a cave, or crossing the terminator, should involve the exposure adapting over a second or two. It is a small thing that makes the shrink-and-walk-in transition feel physical rather than instantaneous.',x:'EYE',e:'S',i:2},
{c:'air',t:'Sky colour from the host star’s spectrum',n:['scatter'],d:'Rayleigh scattering against a 2,600 K blackbody does not produce a blue sky. Convolve the stellar spectrum with the atmospheric composition and the per-ruleset `sky: [r,g,b]` constants disappear, replaced by something derived and defensible.',x:'EYE',e:'M',i:3},
{c:'air',t:'Twilight, crepuscular rays, and a terminator with width',n:['scatter'],d:'The terminator’s softness is a direct function of atmospheric pressure — knife-edged on Selene, tens of kilometres wide on a thick-atmosphere world. It is a physical measurement the player can make by eye.',x:'EYE',e:'M',i:3},
{c:'air',t:'Rainbows, halos and glories',n:['scatter'],d:'A 42° bow from spherical droplets, a 22° halo from hexagonal ice, a glory from droplets of a particular size. Each is diagnostic of the phase and size distribution of what is in the air, so they are simultaneously gorgeous and informative.',x:'EYE',e:'M',i:1},
{c:'air',t:'Atmospheric refraction at the horizon',n:['scatter'],d:'The setting sun is flattened and is already geometrically below the horizon when you see it. On a dense-atmosphere world the effect is extreme enough to bend the horizon upward into a bowl, which is one of the strangest true things about standing on Venus.',x:'EYE',e:'M',i:1},

/* --------------------------------------------------------------- body -- */
{c:'body',t:'Retire the camera-facing quad',k:'mesh',d:'Sixteen hand-drawn SVG sprites on billboards, with a hide term for back-facing ones. Extruded meshes or octahedral impostors give silhouettes that hold up at the Local tier and shade correctly against the terrain they stand on.',x:'EYE',e:'L',i:3},
{c:'body',t:'A body-plan grammar driven by the trait vector',k:'grammar',n:['mesh','traits'],d:'Symmetry, segment count, limb count, appendage type, and proportion generated from the same numbers that selection acts on. This is the change that makes the creatures on screen genuinely the creatures in the model, rather than an illustration of them.',x:'BOTH',e:'L',i:3},
{c:'body',t:'Size derived rather than asserted',n:['grammar'],d:'`W.bodyScale` is a linear function of O₂ clamped to 0.7–1.35. Derive size from oxygen partial pressure, gravity, thermal regime and trophic level, and the giant Carboniferous arthropods, the low-gravity megafauna and the island dwarfs all appear without being authored.',x:'BOTH',e:'M',i:3},
{c:'body',t:'Lineage-inherited morphological constraint',n:['grammar'],d:'Tetrapods have four limbs because their fish ancestors had four fins, and nothing since has changed it. Inheriting body-plan parameters from the phylogeny — and letting them harden — is what makes a clade recognisable as a clade at a glance.',x:'BOTH',e:'M',i:3},
{c:'body',t:'Colour from pigment chemistry',n:['grammar'],d:'Chlorophyll a and b, carotenoids, phycobilins, bacteriorhodopsin, melanin, structural blues. A palette generated from which pigments the lineage actually carries, rather than a per-kind tint, means the world’s colour scheme is an output of its biochemistry.',x:'EYE',e:'M',i:3},
{c:'body',t:'Canopy structure from light competition',n:['npp','mesh'],d:'Height, crown shape and spacing as the equilibrium of a competition for photons. It produces closed canopy in the wet tropics, open savanna where water limits, and krummholz at the treeline — three completely different-looking landscapes from one rule.',x:'BOTH',e:'M',i:3},
{c:'body',t:'Herds, flocks and schools',n:['mesh'],d:'Boids with predator avoidance, over the existing entity system. Aggregation is one of the most legible behaviours at a distance and it is what makes a plain read as populated rather than sprinkled.',x:'EYE',e:'M',i:2},
{c:'body',t:'Movement rate from metabolism and mass',n:['kleiber','mesh'],d:'Stride frequency scales as roughly mass to the minus one-sixth, so small things are frantic and large things are slow. Animating from the same allometry that sets population density means the visual and the simulation cannot drift apart.',x:'EYE',e:'M',i:2},
{c:'body',t:'A proper LOD ladder',n:['mesh'],d:'Statistical density fields from orbit, impostors at regional range, meshes at local range, articulated individuals when held. The current system respawns up to 1,400 sprites on a stride through the cell list, which is the right instinct and the wrong resolution at three of the four tiers.',x:'EYE',e:'M',i:3},
{c:'body',t:'Fossils of the things that actually lived',n:['tree'],d:'When a lineage dies in a cell that is accumulating sediment, record it. Digging one up later and finding a creature the player watched evolve, in the rock layer from the era it lived in, is the payoff for every other item in this document.',x:'BOTH',e:'M',i:3},
{c:'body',t:'Trace fossils',n:['grammar'],d:'Trackways, burrows, borings and nests. They record behaviour rather than anatomy, they are often the only evidence a lineage existed, and the first appearance of vertical burrowing is one of the defining markers of the Cambrian boundary.',x:'BOTH',e:'M',i:2},
{c:'body',t:'Bioluminescence',n:['grammar'],d:'Most of the animals in the deep ocean make their own light, and surface dinoflagellate blooms outline waves and ship wakes for kilometres. On the night side it is the only sign the ocean is alive.',x:'EYE',e:'S',i:3},
{c:'body',t:'The three-pixel silhouette rule',n:['grammar'],d:'Every generated body must remain identifiable in silhouette at the smallest size it will be drawn. Enforce it in the generator with a legibility check, or procedural morphology will produce a planet covered in indistinguishable brown smudges.',x:'EYE',e:'M',i:3},

/* -------------------------------------------------------------- instr -- */
{c:'instr',t:'Rewrite the Chronicle as a scientific record',n:['ext'],d:'Every entry carries what changed, by how much, over what interval, and what it caused — with a link to the fields involved. The current log is 4,000 entries of `{t, kind, cell, mag, label}`, which can say that something happened but never why.',x:'BOTH',e:'M',i:3},
{c:'instr',t:'A phylogeny you can hold',n:['tree'],d:'The tree as a physical object in VR — rotate it, pull a branch to see the trait vector at that node, follow a lineage to its extinction. This is the instrument the entire genome category exists to feed, and in a headset it is a genuinely novel way to read a phylogeny.',x:'BOTH',e:'L',i:3},
{c:'instr',t:'A core sampler',n:['proxy'],d:'Drill anywhere and read the strata your own simulation deposited: the banded iron, the ejecta layer, the coal, the glacial till. It satisfies the product brief’s "every number is a place" rule completely, because the number *is* the place, cut open.',x:'BOTH',e:'M',i:3},
{c:'instr',t:'An ice core with trapped air',n:['proxy'],d:'δ¹⁸O for temperature and bubbles of the actual atmosphere at deposition. Being able to pull a metre of ice out of your own ice cap and read the CO₂ of a hundred thousand years ago is the most direct possible demonstration that the model has memory.',x:'BOTH',e:'M',i:3},
{c:'instr',t:'A live diversity curve',n:['tree'],d:'Sepkoski’s marine genus curve, for your planet — the rises, the plateaus, and the five notches. It is the single image that made mass extinction legible to a general audience, and it can be generated live from the phylogeny.',x:'BOTH',e:'M',i:3},
{c:'instr',t:'Your own Keeling curve',n:['carbon'],d:'Atmospheric CO₂ against time, at whatever resolution the current tick length supports, with the seasonal sawtooth once there is enough land vegetation to cause one. The sawtooth appearing on its own is a small, perfect moment.',x:'BOTH',e:'S',i:3},
{c:'instr',t:'A Whittaker diagram of where your biomes sit',n:['biome'],d:'Plot every land cell in temperature–precipitation space against the classical envelope. A planet whose cells cluster somewhere Earth has no analogue for is immediately, visibly alien, and the player can see exactly how.',x:'BOTH',e:'M',i:3},
{c:'instr',t:'Observe your own planet as an exoplanet',n:['proxy'],d:'Point the transit spectroscopy instrument the worlds backlog already specifies at the world you are standing on. Watching your own oxygen line appear in a transmission spectrum, at a noise level that makes it genuinely ambiguous, teaches more about exoplanet science than any amount of text.',x:'BOTH',e:'M',i:3},
{c:'instr',t:'The redox tower as a physical gauge',n:['redox'],d:'A vertical instrument with the half-reactions on it and the guilds occupying their rungs, filling and emptying as the chemistry changes. It makes the most abstract system in this document into the most watchable one.',x:'BOTH',e:'M',i:3},
{c:'instr',t:'Diff two runs side by side',d:'Fork at a date, run both, and show where the histories diverged — which lineage did not appear, which extinction did not happen, which continent ended up somewhere else. It is the presentation layer for the rewind-the-tape item and it is what makes contingency a felt idea rather than a stated one.',x:'BOTH',e:'M',i:3},
{c:'instr',t:'"Why did this happen" as a causal trace',d:'Select any chronicle event and walk backward through the field values and thresholds that produced it. Every simulation of this depth eventually becomes opaque even to its authors; a causal trace is the difference between a model that teaches and one that merely runs.',x:'BOTH',e:'L',i:3},
{c:'instr',t:'Export the paper',d:'Generate a written history of the world — figures, isotope curves, phylogeny, extinction table, and prose — as an artefact the player keeps. The chronicle exporter already produces a markdown skeleton; this is the version someone would actually show another person.',x:'BOTH',e:'M',i:3},

/* -------------------------------------------------------------- craft -- */
{c:'craft',t:'Move the field solvers to the GPU',d:'Thirty-odd Float32Arrays of NC cells, updated serially in JavaScript every tick. Transform feedback or compute-style fragment passes would buy an order of magnitude, which is what the guild, trait and food-web systems above will need.',x:'SIM',e:'L',i:3},
{c:'craft',t:'Multi-rate integration',d:'Tectonics does not need to run at the same frequency as clouds, and phylogeny does not need to run at the same frequency as tectonics. Explicit per-system rates, driven by the adaptive clock, is what makes deep time affordable.',x:'SIM',e:'M',i:3},
{c:'craft',t:'One seeded RNG stream, everywhere',d:'`Math.random()` appears throughout `bio.js`, `agents.js` and `world.js`, which makes runs unreproducible and the rewind-the-tape feature impossible. A per-system seeded stream is a small refactor with a large payoff.',x:'SIM',e:'S',i:3},
{c:'craft',t:'Save, load and replay from the event log',d:'A world is a seed, a ruleset and an ordered list of interventions. Storing those three things reproduces any history exactly, and it is what lets a player share a planet rather than a screenshot.',x:'SIM',e:'M',i:3},
{c:'craft',t:'Regression-test Earth against Earth',d:'The Earth ruleset should reproduce Earth’s history within a stated tolerance: oxygen rising when it did, the snowballs happening, the extinctions landing in the right order. It is the only honest way to claim the model is calibrated, and it will fail informatively for years.',x:'SIM',e:'M',i:3},
{c:'craft',t:'A calibration harness mapping sim units to SI',d:'`temp` runs 0–1.6 and stands in for kelvin; `life` is dimensionless; `year` advances 200 per tick. Publish the conversion, and any number the player reads can be checked against a textbook.',x:'BOTH',e:'M',i:3},
{c:'craft',t:'Annotate every constant with its provenance',d:'Measured, fitted, or invented for legibility — one of three, on every magic number in the sim directory. `bioTick` currently contains `photosynth += bio * 0.00000008` with no indication which of the three it is, and that ambiguity is the thing that will eventually make the model indefensible.',x:'SIM',e:'M',i:3},
{c:'craft',t:'Publish the model’s limits with the model',d:'A short, plain document listing what this simulation deliberately does not do — no radiative transfer, no real ocean dynamics, a 6×N² cube-sphere at whatever resolution ships. Stating the boundary is what earns trust for everything inside it.',x:'BOTH',e:'S',i:3},

/* Phase 0 biosphere rebuild — shipped ahead of the 200-item backlog */
{c:'chem',t:'Chemistry memory via relaxing species fields',k:'species',d:'Dissolved donors and acceptors (`H2S`, `Fe²⁺`, `orgC`, …) now relax toward abiotic equilibrium each tick instead of resetting. Vent H₂ plumes diffuse a few cells; the Archean ocean remembers its redox state. The Lab readout shows the three slowest fields.',x:'SIM',e:'M',i:3},
{c:'genome',t:'Lineage lookup by id, not array scan',n:['tree'],d:'`tree.byId` and `nodeOf()` replace `nodes.find` everywhere. Speciation, convergence detection, and agent assignment all key off stable lineage ids — the prerequisite for anything phylogenetic at scale.',x:'SIM',e:'S',i:2},
{c:'genome',t:'Derived lifeClass as a compatibility shim',n:['tree'],d:'`lifeClass` and `unlockedClass` are written once per tick by `deriveLifeClass()` from guild density and the phylogeny, not by morphology gates. Existing colour and overlay code keeps working while the redox tower becomes the source of truth.',x:'SIM',e:'S',i:2},
{c:'surface',t:'Fractal coastlines after plate isostasy',d:'Domain-warped fBm perturbs elevation strongest at sea level, with Laplacian coastal smoothing, so Voronoi plate cells read as natural continents rather than polygon facets. Applied in `terrainShape.js` for all worlds and refined again for Earth.',x:'EYE',e:'S',i:2},
];

/* ------------------------------------------------------------- derive -- */
D.forEach((x, i) => { x.id = i + 1; });

const byCat = (id) => D.filter((x) => x.c === id);
const count = (f) => D.filter(f).length;
const AX = { SIM: 'Sim', EYE: 'Eye', BOTH: 'Both' };

const provides = new Map();
for (const x of D) if (x.k) provides.set(x.k, x);
function dependents(tok) {
  return D.filter((y) => (y.n || []).includes(tok)).length;
}
const CRITICAL = [...provides.keys()]
  .map((k) => ({ k, x: provides.get(k), n: dependents(k) }))
  .filter((r) => r.n > 0)
  .sort((a, b) => b.n - a.n);

/* ------------------------------------------------------------ markdown -- */
function markdown() {
  const L = [];
  L.push('# ORRERY — evolution & fidelity backlog');
  L.push('');
  L.push(`**${D.length} items.** Generated from \`scripts/evolution.mjs\` — edit that file, not this one, then run \`node scripts/evolution.mjs\`.`);
  L.push('');
  L.push('This is the third backlog. The first covers the systems SimEarth had; the second covers the 120 real worlds to put them on. This one covers the thing both of those exist to serve: **making the evolution of life on a planet something you can watch happen, over deep time, and believe.**');
  L.push('');
  L.push(`Axis: **${count((x) => x.x === 'SIM')}** simulation truth, **${count((x) => x.x === 'EYE')}** what the player sees, **${count((x) => x.x === 'BOTH')}** both. Effort is S/M/L. Impact is 1–3, where 3 means the thesis does not land without it.`);
  L.push('');

  L.push('## Where the prototype actually is');
  L.push('');
  L.push('Read honestly, so the list below has something to be measured against.');
  L.push('');
  L.push('- **The clock.** 200 years a tick, uniform. Eras are named every 48,000 years from an eight-branch `if` chain in `chronicle.js`. There is no geologic timescale, and the Hadean is 24 silent warmup ticks in `generate()` with the biosphere paused so the globe does not turn green.');
  L.push('- **Life.** One `Float32Array` of density and one `Uint8Array` of class index, against eight hard-coded classes from `prokaryote` to `mammal` in `sim/bio.js`. Advancement is gated on `W.year >= (unlockedClass + 1) * 5000` — a year counter, not a condition. Trophic structure is three global scalars. There is no genome, no lineage, no tree, and no extinction that is not a dieback in density.');
  L.push('- **Chemistry.** Seven gases as volume mixing ratios, a log-forcing greenhouse, a one-line silicate weathering term, and photosynthesis as a pair of constants (`0.00000008` and `0.000000025`) applied to total biomass. Oxygen accumulates directly from photosynthesis rather than from carbon burial, which is the wrong mechanism in a way that matters.');
  L.push('- **The good parts.** Plate tectonics, boundary classification, hotspots, erosion with sediment routing, a real water budget, three-cell circulation, obliquity, sea ice separated from land ice, a dust cycle, tsunamis, and a 120-world catalogue that maps real bodies onto playable rulesets. The geosphere and hydrosphere are genuinely ahead of the biosphere, and that gap is the whole opportunity.');
  L.push('- **The picture.** WebGL2, a cube-sphere with vertex colours from per-ruleset colour functions, an analytic atmosphere rim, a translucent cloud shell, and sixteen SVG sprites on camera-facing quads. It is well made and it is a diagram of a planet rather than a planet.');
  L.push('');

  L.push('## The shape of a good run');
  L.push('');
  L.push('If all two hundred items landed, this is what a four-and-a-half-billion-year Earth run should feel like — the arc the list is arranged to produce.');
  L.push('');
  const ARC = [
    ['Accretion → 4.4 Ga', 'A magma ocean cooling under a dim sun, a Moon torn out of the side of it, and the first liquid water condensing onto crust that keeps being destroyed. Nothing is alive and the geology is doing all the work.'],
    ['4.0 → 2.5 Ga', 'Hydrogen from cracked rock at the vents. Something starts copying itself. For half a billion years the only visible sign is a faint iridescence on shallow flats — mats, then stromatolites — while a methane haze thickens overhead and the sky is orange.'],
    ['2.45 → 2.0 Ga', 'One lineage learns to split water. Iron drops out of the ocean in bands you will be able to core four billion years later; the haze clears; the sky turns blue for the first time; and most of what was alive dies of the new air.'],
    ['1.8 → 0.8 Ga', 'A billion years where almost nothing happens, and the reason is legible — sulfidic oceans, no trace metals, no phosphorus, a complex cell that exists and cannot afford to become anything. The player has to sit in it, and the isotope curves are flat while they do.'],
    ['720 → 540 Ma', 'Ice to the equator, twice, and a planet that only escapes because volcanoes keep breathing under the lid. Then oxygen climbs again and within a geological instant there are eyes, shells, and things that hunt.'],
    ['470 → 250 Ma', 'Green climbs out of the water and onto the rock, and immediately breaks the planet — weathering triples, CO₂ collapses, the ocean suffocates. Forests bury carbon nothing can digest, oxygen reaches 35%, and the world burns. Then Siberia opens and 81% of everything in the sea is gone.'],
    ['250 → 66 Ma', 'Recovery over ten million years, then the largest land animals the planet will ever carry, then ten kilometres of rock arriving at 20 km/s and two years without a summer.'],
    ['66 Ma → now', 'Grass, ice, the ocean conveyor switching on, and a lineage that starts moving carbon out of the rock and back into the air roughly ten thousand times faster than the thermostat can answer.'],
  ];
  L.push('| Interval | What the player is watching |');
  L.push('|---|---|');
  for (const [a, b] of ARC) L.push(`| **${a}** | ${b} |`);
  L.push('');

  L.push('## The critical path');
  L.push('');
  L.push('The capabilities the largest number of other items are waiting on. Nothing below them can be honest until they exist.');
  L.push('');
  L.push('| Capability | Item | Unblocks |');
  L.push('|---|---|---|');
  for (const r of CRITICAL.slice(0, 12)) {
    L.push(`| \`${r.k}\` | ${r.x.id}. ${r.x.t} | ${r.n} items |`);
  }
  L.push('');

  for (const [id, name, blurb] of CATS) {
    const items = byCat(id);
    L.push(`## ${name} — ${items.length}`);
    L.push('');
    L.push(`_${blurb}_`);
    L.push('');
    L.push('| # | Item | Detail | Axis | Effort | Impact |');
    L.push('|---|---|---|---|---|---|');
    for (const x of items) {
      const gives = x.k ? ` <br>gives \`${x.k}\`` : '';
      const needs = x.n?.length ? ` <br>needs ${x.n.map((t) => '`' + t + '`').join(' ')}` : '';
      L.push(`| ${x.id} | **${x.t}**${gives}${needs} | ${x.d} | ${AX[x.x]} | ${x.e} | ${x.i} |`);
    }
    L.push('');
  }

  L.push('## Sequencing');
  L.push('');
  L.push('Four blocks, in order. Each is worth shipping alone.');
  L.push('');
  L.push('1. **Make time honest.** `clock`, `logtime`, `chart`, `faint`. Everything else is unreadable until a tick means a defensible number of years and the era ribbon shows real proportions. Cheapest block on the list and the one that changes the most.');
  L.push('2. **Make life chemical.** `redox`, `species`, `carbon`, `oxyphoto`, and oxygen-from-burial. This is the SimEarth thesis, rebuilt on the modern understanding, and it makes the first three billion years worth playing.');
  L.push('3. **Make life evolve.** `traits`, `spec`, `tree`, plus the ecology and biogeography categories. This is where the ladder becomes a tree you did not author and the player starts seeing things they were not shown.');
  L.push('4. **Make it beautiful.** `pbr`, `scatter`, `hdr`, `mesh`, `grammar`. The rendering work is deliberately last because most of it is a way of *displaying* the systems above — and because scattering and PBR are the two items that make everything already in the engine look like a photograph.');
  L.push('');
  L.push('The instruments in category 14 should be built alongside whatever they read, not after. An instrument written at the same time as its system is a design constraint on that system, and a good one.');
  L.push('');

  return L.join('\n');
}

/* ----------------------------------------------------------------- html -- */
function html() {
  const data = JSON.stringify(D.map((x) => ({
    id: x.id, c: x.c, t: x.t, d: x.d, x: x.x, e: x.e, i: x.i, k: x.k || '', n: x.n || [],
  })));
  const cats = JSON.stringify(CATS.map(([id, name, blurb]) => ({ id, name, blurb })));
  const crit = JSON.stringify(CRITICAL.slice(0, 12).map((r) => ({ k: r.k, id: r.x.id, t: r.x.t, n: r.n })));
  return `<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<title>ORRERY — 200 ways to make evolution legible</title>
<style>
:root{
  --ground:#0c0f16; --panel:#151a24; --panel2:#1b2231; --rule:#252d3d;
  --text:#dbe1ec; --dim:#98a3b7; --faint:#6c7688;
  --accent:#7ec89a; --accent-soft:rgba(126,200,154,.13); --accent-line:rgba(126,200,154,.34);
  --sim:#7fb0e0; --sim-soft:rgba(127,176,224,.14);
  --eye:#e0a050; --eye-soft:rgba(224,160,80,.14);
  --sans:-apple-system,BlinkMacSystemFont,"Helvetica Neue","Segoe UI",Roboto,sans-serif;
  --mono:ui-monospace,"SF Mono",SFMono-Regular,Menlo,Consolas,monospace;
  --serif:"Iowan Old Style","Palatino Linotype",Palatino,Georgia,serif;
}
@media (prefers-color-scheme: light){
  :root{ --ground:#eef0f3; --panel:#fff; --panel2:#f5f6f9; --rule:#d9dde5;
    --text:#12151c; --dim:#4e5768; --faint:#727d90;
    --accent:#2c7a52; --accent-soft:rgba(44,122,82,.09); --accent-line:rgba(44,122,82,.3);
    --sim:#215e93; --sim-soft:rgba(33,94,147,.09); --eye:#9a5f14; --eye-soft:rgba(154,95,20,.09); }
}
:root[data-theme="dark"]{ --ground:#0c0f16; --panel:#151a24; --panel2:#1b2231; --rule:#252d3d;
  --text:#dbe1ec; --dim:#98a3b7; --faint:#6c7688;
  --accent:#7ec89a; --accent-soft:rgba(126,200,154,.13); --accent-line:rgba(126,200,154,.34);
  --sim:#7fb0e0; --sim-soft:rgba(127,176,224,.14); --eye:#e0a050; --eye-soft:rgba(224,160,80,.14); }
:root[data-theme="light"]{ --ground:#eef0f3; --panel:#fff; --panel2:#f5f6f9; --rule:#d9dde5;
  --text:#12151c; --dim:#4e5768; --faint:#727d90;
  --accent:#2c7a52; --accent-soft:rgba(44,122,82,.09); --accent-line:rgba(44,122,82,.3);
  --sim:#215e93; --sim-soft:rgba(33,94,147,.09); --eye:#9a5f14; --eye-soft:rgba(154,95,20,.09); }

*{box-sizing:border-box;}
body{margin:0; background:var(--ground); color:var(--text);
     font:400 16px/1.6 var(--sans); -webkit-font-smoothing:antialiased;}
.wrap{max-width:1080px; margin:0 auto; padding:40px 26px 110px;}

header{border-bottom:1px solid var(--rule); padding-bottom:28px;}
.eyebrow{font:500 10.5px/1 var(--mono); letter-spacing:.24em; text-transform:uppercase; color:var(--accent);}
h1{font:700 clamp(34px,5.4vw,54px)/1.03 var(--sans); letter-spacing:-.035em; margin:15px 0 0; text-wrap:balance;}
.sub{font:italic 400 clamp(17px,2.2vw,21px)/1.45 var(--serif); color:var(--dim);
     margin:18px 0 0; max-width:48ch;}
.nav{margin-top:20px; font:400 12.5px/1.7 var(--mono); color:var(--faint);}
.nav a{color:var(--dim); text-decoration:none; border-bottom:1px solid var(--rule);}
.nav a:hover{color:var(--accent); border-color:var(--accent-line);}

.tally{display:grid; grid-template-columns:repeat(auto-fit,minmax(126px,1fr)); gap:1px;
       background:var(--rule); border:1px solid var(--rule); border-radius:8px;
       overflow:hidden; margin-top:26px;}
.tally > div{background:var(--panel); padding:13px 15px;}
.tally dt{font:500 9.5px/1 var(--mono); letter-spacing:.15em; text-transform:uppercase; color:var(--faint);}
.tally dd{margin:9px 0 0; font:600 26px/1 var(--sans); letter-spacing:-.02em;
          font-variant-numeric:tabular-nums;}
.tally dd small{display:block; font:400 11px/1.5 var(--mono); color:var(--faint); margin-top:6px; letter-spacing:0;}

.prose{margin-top:40px;}
.prose h2{font:650 21px/1.2 var(--sans); letter-spacing:-.022em; margin:0 0 12px;
          border-bottom:1px solid var(--rule); padding-bottom:10px;}
.prose p{color:var(--dim); max-width:74ch; font-size:14.5px;}
.state{list-style:none; margin:14px 0 0; padding:0; display:flex; flex-direction:column; gap:1px;
       background:var(--rule); border:1px solid var(--rule); border-radius:8px; overflow:hidden;}
.state li{background:var(--panel); padding:13px 16px; color:var(--dim); font-size:13.5px; line-height:1.6;}
.state b{color:var(--text); font-weight:600;}
.arc{width:100%; border-collapse:collapse; margin-top:14px; font-size:13.5px;}
.arc td{border-top:1px solid var(--rule); padding:12px 14px; color:var(--dim); vertical-align:top;}
.arc td:first-child{white-space:nowrap; color:var(--accent); font:500 11.5px/1.7 var(--mono); width:1%;}
.crit{width:100%; border-collapse:collapse; margin-top:14px; font-size:13.5px;}
.crit td{border-top:1px solid var(--rule); padding:9px 12px; color:var(--dim);}
.crit td:first-child{font:500 11.5px/1.6 var(--mono); color:var(--accent); width:1%; white-space:nowrap;}
.crit td:last-child{text-align:right; font:500 11.5px/1.6 var(--mono); color:var(--faint); white-space:nowrap;}
.seq{margin:14px 0 0; padding-left:20px; color:var(--dim); font-size:14px;}
.seq li{margin-bottom:9px; max-width:74ch;}
.seq b{color:var(--text);}
code{font:500 12.5px/1 var(--mono); background:var(--panel2); border:1px solid var(--rule);
     padding:2px 5px; border-radius:4px; color:var(--accent);}

.controls{position:sticky; top:0; z-index:5; background:var(--ground);
          padding:18px 0 14px; border-bottom:1px solid var(--rule); margin:44px 0 6px;}
.filters{display:flex; flex-wrap:wrap; gap:7px; align-items:center;}
.flabel{font:500 9.5px/1 var(--mono); letter-spacing:.17em; text-transform:uppercase;
        color:var(--faint); margin-right:3px;}
button.f{font:500 11.5px/1 var(--mono); color:var(--dim); cursor:pointer; background:transparent;
         border:1px solid var(--rule); border-radius:5px; padding:7px 10px;}
button.f:hover{border-color:var(--accent-line); color:var(--text);}
button.f[aria-pressed="true"]{background:var(--accent-soft); border-color:var(--accent-line); color:var(--accent);}
button.f.sim[aria-pressed="true"]{background:var(--sim-soft); border-color:var(--sim); color:var(--sim);}
button.f.eye[aria-pressed="true"]{background:var(--eye-soft); border-color:var(--eye); color:var(--eye);}
#q{flex:1; min-width:170px; font:400 13px/1 var(--sans); color:var(--text);
   background:var(--panel); border:1px solid var(--rule); border-radius:5px; padding:8px 11px;}
#q::placeholder{color:var(--faint);}
.tally2{margin-top:11px; font:500 11px/1 var(--mono); color:var(--faint); font-variant-numeric:tabular-nums;}

section{padding-top:38px; scroll-margin-top:120px;}
.sechead{display:flex; align-items:baseline; gap:12px; flex-wrap:wrap;
         border-bottom:1px solid var(--rule); padding-bottom:10px;}
.sechead h2{font:650 21px/1.2 var(--sans); letter-spacing:-.022em; margin:0;}
.sechead .n{font:500 10.5px/1 var(--mono); color:var(--accent); background:var(--accent-soft);
            border:1px solid var(--accent-line); padding:4px 7px; border-radius:4px;}
.blurb{margin:13px 0 0; color:var(--dim); max-width:74ch; font-size:14.5px;}

ol{list-style:none; margin:16px 0 0; padding:0; display:flex; flex-direction:column; gap:1px;
   background:var(--rule); border:1px solid var(--rule); border-radius:8px; overflow:hidden;}
li.item{background:var(--panel); padding:13px 16px; display:grid;
   grid-template-columns:38px minmax(0,1fr) auto; gap:4px 14px; align-items:baseline;}
li .id{font:500 11px/1.5 var(--mono); color:var(--faint); font-variant-numeric:tabular-nums;}
li .t{font:600 14.5px/1.4 var(--sans); letter-spacing:-.008em;}
li .d{grid-column:2; color:var(--dim); font-size:13.5px; line-height:1.55; max-width:76ch;}
li .dep{grid-column:2; font:400 11px/1.6 var(--mono); color:var(--faint); margin-top:4px;}
li .dep .gives{color:var(--accent);}
li .tags{display:flex; gap:5px; align-items:center; grid-row:1; grid-column:3;}
.tag{font:600 9px/1 var(--mono); letter-spacing:.1em; text-transform:uppercase;
     padding:4px 6px; border-radius:3px; white-space:nowrap; border:1px solid transparent;}
.tag.sim{background:var(--sim-soft); color:var(--sim); border-color:var(--sim);}
.tag.eye{background:var(--eye-soft); color:var(--eye); border-color:var(--eye);}
.tag.both{background:transparent; color:var(--dim); border-color:var(--rule);}
.tag.e{background:transparent; color:var(--faint); border-color:var(--rule);}
.dots{display:inline-flex; gap:2px;}
.dots i{width:5px; height:5px; border-radius:50%; background:var(--rule); display:block;}
.dots i.on{background:var(--accent);}
.empty{padding:44px 16px; text-align:center; color:var(--faint); font:400 13.5px/1.6 var(--mono);}
:focus-visible{outline:2px solid var(--accent); outline-offset:2px; border-radius:4px;}
footer{margin-top:64px; padding-top:22px; border-top:1px solid var(--rule);
       font:400 12px/1.7 var(--mono); color:var(--faint);}
@media (max-width:640px){
  li.item{grid-template-columns:30px minmax(0,1fr);}
  li .tags{grid-row:auto; grid-column:2; margin-top:7px;}
  .arc td:first-child{white-space:normal;}
}
@media (prefers-reduced-motion: reduce){ *{transition:none !important;} }
</style>
<link rel="stylesheet" href="doc-responsive.css">

<div class="wrap">
<header>
  <div class="eyebrow">Backlog three · evolution &amp; fidelity</div>
  <h1>200 ways to make evolution legible</h1>
  <p class="sub">The first backlog covers the systems. The second covers the worlds. This one covers
  the only thing either exists to serve — watching life happen on a planet, over deep time, and believing it.</p>
  <p class="nav"><a href="./">Pitch</a> · <a href="backlog.html">Systems backlog</a> ·
  <a href="worlds.html">Worlds</a> · <a href="godgame.html">God layer</a> ·
  <a href="next.html">Next 200</a> ·
  <a href="tides-weather.html">Tides &amp; weather</a> · <a href="geology.html">Geology</a> · <a href="exoparams.html">Real parameters</a> · <a href="living.html">Alive</a> · <a href="currents.html">Currents</a> ·
  <a href="realism.html">Realism</a> · <a href="life.html">Life</a> · <a href="surface.html">Surface</a> · <a href="worldspace.html">World space</a> · <a href="openworld.html">Open world</a> · <a href="../vr/">Prototype</a></p>
  <dl class="tally">
    <div><dt>Items</dt><dd>200<small>15 categories</small></dd></div>
    <div><dt>Axis</dt><dd>${count((x) => x.x === 'SIM')} / ${count((x) => x.x === 'EYE')}<small>sim · eye (+${count((x) => x.x === 'BOTH')} both)</small></dd></div>
    <div><dt>Impact 3</dt><dd>${count((x) => x.i === 3)}<small>of 200</small></dd></div>
    <div><dt>Effort</dt><dd>${count((x) => x.e === 'S')}/${count((x) => x.e === 'M')}/${count((x) => x.e === 'L')}<small>S / M / L</small></dd></div>
  </dl>
</header>

<div class="prose">
  <h2>Where the prototype actually is</h2>
  <ul class="state">
    <li><b>The clock.</b> 200 years a tick, uniform. Eras are named every 48,000 years from an eight-branch <code>if</code> chain. There is no geologic timescale, and the Hadean is 24 silent warmup ticks with the biosphere paused so the globe does not turn green.</li>
    <li><b>Life.</b> One density array and one class index, against eight hard-coded classes from prokaryote to mammal. Advancement is gated on a year counter, not a condition. Trophic structure is three global scalars. No genome, no lineage, no tree.</li>
    <li><b>Chemistry.</b> Seven gases, a log-forcing greenhouse, a one-line weathering term, and photosynthesis as two magic constants. Oxygen accumulates directly from photosynthesis rather than from carbon burial — the wrong mechanism, in a way that matters.</li>
    <li><b>The good parts.</b> Plate tectonics with classified boundaries, hotspots, stream-power erosion, a closed water budget, three-cell circulation, obliquity, sea ice separated from land ice, and a 120-world catalogue. The geosphere is well ahead of the biosphere, and that gap is the opportunity.</li>
    <li><b>The picture.</b> WebGL2, a cube-sphere with vertex colours from per-ruleset colour functions, an analytic rim, a cloud shell, and sixteen SVG sprites on billboards. Well made, and a diagram of a planet rather than a planet.</li>
  </ul>

  <h2 style="margin-top:40px">The shape of a good run</h2>
  <p>If all two hundred landed, this is what four and a half billion years should feel like.</p>
  <table class="arc"><tbody id="arc"></tbody></table>

  <h2 style="margin-top:40px">The critical path</h2>
  <p>The capabilities the largest number of other items wait on.</p>
  <table class="crit"><tbody id="crit"></tbody></table>
</div>

<div class="controls">
  <div class="filters">
    <span class="flabel">Axis</span>
    <button class="f sim" data-k="x" data-v="SIM" aria-pressed="false">Sim</button>
    <button class="f eye" data-k="x" data-v="EYE" aria-pressed="false">Eye</button>
    <button class="f" data-k="x" data-v="BOTH" aria-pressed="false">Both</button>
    <span class="flabel" style="margin-left:9px">Effort</span>
    <button class="f" data-k="e" data-v="S" aria-pressed="false">S</button>
    <button class="f" data-k="e" data-v="M" aria-pressed="false">M</button>
    <button class="f" data-k="e" data-v="L" aria-pressed="false">L</button>
    <span class="flabel" style="margin-left:9px">Impact</span>
    <button class="f" data-k="i" data-v="3" aria-pressed="false">3</button>
    <button class="f" data-k="i" data-v="2" aria-pressed="false">2</button>
    <button class="f" data-k="i" data-v="1" aria-pressed="false">1</button>
    <input id="q" type="search" placeholder="Search 200 items…" aria-label="Search items">
  </div>
  <div class="tally2" id="shown"></div>
</div>

<div id="list"></div>

<footer>
  Generated from <code>scripts/evolution.mjs</code> — edit the source and re-run, do not edit the output.<br>
  SimEarth is a trademark of Electronic Arts; referenced as prior art only. Dates and figures are
  current consensus where consensus exists and are flagged as contested where it does not.
</footer>
</div>

<script>
"use strict";
var DATA = ${data};
var CATS = ${cats};
var CRIT = ${crit};
var ARC = ${JSON.stringify([
  ['Accretion → 4.4 Ga', 'A magma ocean cooling under a dim sun, a Moon torn out of the side of it, and the first liquid water condensing onto crust that keeps being destroyed. Nothing is alive and the geology is doing all the work.'],
  ['4.0 → 2.5 Ga', 'Hydrogen from cracked rock at the vents. Something starts copying itself. For half a billion years the only visible sign is a faint iridescence on shallow flats, while a methane haze thickens overhead and the sky is orange.'],
  ['2.45 → 2.0 Ga', 'One lineage learns to split water. Iron drops out of the ocean in bands you will core four billion years later; the haze clears; the sky turns blue for the first time; and most of what was alive dies of the new air.'],
  ['1.8 → 0.8 Ga', 'A billion years where almost nothing happens, and the reason is legible — sulfidic oceans, no trace metals, no phosphorus. The player has to sit in it, and the isotope curves are flat while they do.'],
  ['720 → 540 Ma', 'Ice to the equator, twice, and a planet that only escapes because volcanoes keep breathing under the lid. Then oxygen climbs again and within a geological instant there are eyes, shells, and things that hunt.'],
  ['470 → 250 Ma', 'Green climbs onto the rock and immediately breaks the planet — weathering triples, CO₂ collapses, the ocean suffocates. Forests bury carbon nothing can digest, oxygen reaches 35%, the world burns. Then Siberia opens.'],
  ['250 → 66 Ma', 'Recovery over ten million years, then the largest land animals the planet will ever carry, then ten kilometres of rock arriving at 20 km/s and two years without a summer.'],
  ['66 Ma → now', 'Grass, ice, the ocean conveyor switching on, and a lineage that moves carbon out of the rock and back into the air about ten thousand times faster than the thermostat can answer.'],
])};
var AXLABEL = {SIM:'Sim', EYE:'Eye', BOTH:'Both'};
var active = {x:new Set(), e:new Set(), i:new Set()};
var query = '';
var listEl = document.getElementById('list');
var shownEl = document.getElementById('shown');

function esc(s){ return String(s).replace(/[&<>"]/g, function(c){
  return ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'})[c]; }); }

document.getElementById('arc').innerHTML = ARC.map(function(r){
  return '<tr><td>' + esc(r[0]) + '</td><td>' + esc(r[1]) + '</td></tr>'; }).join('');
document.getElementById('crit').innerHTML = CRIT.map(function(r){
  return '<tr><td>' + esc(r.k) + '</td><td>' + r.id + '. ' + esc(r.t) +
         '</td><td>' + r.n + ' items</td></tr>'; }).join('');

function match(o){
  if (active.x.size && !active.x.has(o.x)) return false;
  if (active.e.size && !active.e.has(o.e)) return false;
  if (active.i.size && !active.i.has(String(o.i))) return false;
  if (query){
    var hay = (o.t + ' ' + o.d + ' ' + o.k + ' ' + o.n.join(' ')).toLowerCase();
    if (hay.indexOf(query) === -1) return false;
  }
  return true;
}

function dots(n){
  var out = '<span class="dots" title="Impact ' + n + ' of 3">';
  for (var k = 1; k <= 3; k++) out += '<i class="' + (k <= n ? 'on' : '') + '"></i>';
  return out + '</span>';
}

function render(){
  var html = '', total = 0;
  for (var ci = 0; ci < CATS.length; ci++){
    var cat = CATS[ci];
    var items = DATA.filter(function(o){ return o.c === cat.id && match(o); });
    if (!items.length) continue;
    total += items.length;
    html += '<section id="' + cat.id + '"><div class="sechead"><h2>' + esc(cat.name) +
            '</h2><span class="n">' + items.length + '</span></div>' +
            '<p class="blurb">' + esc(cat.blurb) + '</p><ol>';
    for (var k = 0; k < items.length; k++){
      var o = items[k];
      var cls = o.x === 'SIM' ? 'sim' : o.x === 'EYE' ? 'eye' : 'both';
      var dep = '';
      if (o.k) dep += '<span class="gives">gives ' + esc(o.k) + '</span>';
      if (o.n.length) dep += (dep ? ' · ' : '') + 'needs ' + o.n.map(esc).join(' ');
      html += '<li class="item"><span class="id">' + o.id + '</span>' +
              '<span class="t">' + esc(o.t) + '</span>' +
              '<span class="tags"><span class="tag ' + cls + '">' + AXLABEL[o.x] + '</span>' +
              '<span class="tag e">' + o.e + '</span>' + dots(o.i) + '</span>' +
              '<span class="d">' + esc(o.d) + '</span>' +
              (dep ? '<span class="dep">' + dep + '</span>' : '') + '</li>';
    }
    html += '</ol></section>';
  }
  if (!total) html = '<p class="empty">Nothing matches those filters.</p>';
  listEl.innerHTML = html;
  shownEl.textContent = 'Showing ' + total + ' of ' + DATA.length;
}

var btns = document.querySelectorAll('button.f');
for (var b = 0; b < btns.length; b++){
  btns[b].addEventListener('click', function(){
    var k = this.dataset.k, v = this.dataset.v;
    if (active[k].has(v)) { active[k].delete(v); this.setAttribute('aria-pressed','false'); }
    else { active[k].add(v); this.setAttribute('aria-pressed','true'); }
    render();
  });
}
document.getElementById('q').addEventListener('input', function(){
  query = this.value.trim().toLowerCase(); render();
});
render();
</script>
`;
}

/* ----------------------------------------------------------------- emit -- */
await mkdir(join(ROOT, 'briefs'), { recursive: true });
await mkdir(join(ROOT, 'site'), { recursive: true });
await writeFile(join(ROOT, 'briefs', 'evolution-backlog.md'), markdown() + '\n');
await writeFile(join(ROOT, 'site', 'evolution.html'), html());

console.log(`evolution: ${D.length} items across ${CATS.length} categories`);
for (const [id, name] of CATS) console.log(`  ${String(byCat(id).length).padStart(3)}  ${name}`);
console.log(`\naxis     sim ${count((x) => x.x === 'SIM')} · eye ${count((x) => x.x === 'EYE')} · both ${count((x) => x.x === 'BOTH')}`);
console.log(`effort   S ${count((x) => x.e === 'S')} · M ${count((x) => x.e === 'M')} · L ${count((x) => x.e === 'L')}`);
console.log(`impact   3 ${count((x) => x.i === 3)} · 2 ${count((x) => x.i === 2)} · 1 ${count((x) => x.i === 1)}`);
console.log('\ncritical path:');
for (const r of CRITICAL.slice(0, 12)) {
  console.log(`  ${String(r.n).padStart(3)}  ${r.k.padEnd(10)} ${r.x.t}`);
}
const unmet = new Set();
for (const x of D) for (const t of x.n || []) if (!provides.has(t)) unmet.add(t);
if (unmet.size) console.log(`\nWARNING unmet tokens: ${[...unmet].join(', ')}`);
console.log('\nwrote briefs/evolution-backlog.md and site/evolution.html');
